function parsearRespuestaAjaxFlexible(responseText) {
	if (typeof responseText === "string") {
		return $.parseJSON(responseText);
	}
	return responseText || {};
}

function textoRespuestaAjaxFlexible(responseText) {
	if (typeof responseText === "string") {
		return responseText;
	}
	try {
		return JSON.stringify(responseText);
	} catch (error) {
		return String(responseText);
	}
}

function cambiarTabFichaClinicaConsulta(tab, opciones) {
	opciones = opciones || {};
	var raiz = document.getElementById("divAbmConsulta");
	if (!raiz) {
		return false;
	}
	var destino = tab || "plan";
	window.consultaFichaTabActiva = destino;
	var botones = raiz.querySelectorAll("[data-consulta-tab-button]");
	for (var i = 0; i < botones.length; i++) {
		var boton = botones[i];
		var activo = boton.getAttribute("data-consulta-tab-button") == destino;
		if (boton.classList) {
			boton.classList.toggle("is-active", activo);
		}
		boton.setAttribute("aria-selected", activo ? "true" : "false");
	}
	var paneles = raiz.querySelectorAll("[data-consulta-tab-panel]");
	for (var j = 0; j < paneles.length; j++) {
		var panel = paneles[j];
		var panelActivo = panel.getAttribute("data-consulta-tab-panel") == destino;
		if (panel.classList) {
			panel.classList.toggle("is-active", panelActivo);
		}
		if (panelActivo) {
			panel.removeAttribute("hidden");
			panel.style.removeProperty("display");
		} else {
			panel.setAttribute("hidden", "hidden");
			panel.style.setProperty("display", "none", "important");
		}
	}
	if (destino == "odontograma" && opciones.recargarOdontograma !== false
		&& typeof cargarOdontogramaFichaClinica == "function") {
		setTimeout(function () {
			try {
				cargarOdontogramaFichaClinica(opciones.opcionesOdontograma || {});
			} catch (error) {
				console.error("No se pudo refrescar el odontograma de la ficha clinica:", error);
			}
		}, 80);
	}
	if (opciones.enfocar === true) {
		setTimeout(function () {
			var panelActivo = raiz.querySelector("[data-consulta-tab-panel='" + destino + "']");
			if (!panelActivo) { return; }
			if (!panelActivo.hasAttribute("tabindex")) { panelActivo.setAttribute("tabindex", "-1"); }
			try { panelActivo.focus({ preventScroll: true }); } catch (error) { panelActivo.focus(); }
			if (typeof panelActivo.scrollIntoView === "function") {
				try { panelActivo.scrollIntoView({ behavior: "smooth", block: "start" }); }
				catch (error) { panelActivo.scrollIntoView(true); }
			}
		}, opciones.demoraEnfoque || 0);
	}
	return false;
}

function prepararTabsFichaClinicaConsulta() {
	cambiarTabFichaClinicaConsulta(window.consultaFichaTabActiva || "plan");
}

if (document.addEventListener) {
	document.addEventListener("DOMContentLoaded", function () {
		prepararTabsFichaClinicaConsulta();
	});
}

