	document.getElementById('inptContenidoAbmMensaje')
		.addEventListener('keyup', function(e) {
		const editorMenciones = e.currentTarget;
		contadorLongitudMensaje = editorMenciones.textContent.length;

		// Actualizar el contador de pantalla
		document.getElementById('limiteCaracteresMensajeInterconsulta').innerText= contadorLongitudMensaje;
		
		if (editorMenciones && editorMenciones.classList.contains('mensaje-interconsulta')) {
			const valor = editorMenciones.textContent;
			const match = valor.match(/@(\w*)$/); // detecta @ + texto
			if (match) {
				const textoBusqueda = match[1].toLowerCase();
				const mostrarSugerenciasMenciones = function() {
					const sugerencias = Object.entries(registroUsuariosInterconsulta)
						.filter(([id, nombre]) => String(nombre || '').toLowerCase().includes(textoBusqueda));

					mostrarOpcionesUsuariosMenciones(editorMenciones, sugerencias);
					document.getElementById('dropdown-menciones').style.display= "";
				};

				if (Object.keys(registroUsuariosInterconsulta).length == 0) {
					cargarUsuariosMencionesInterConsulta(mostrarSugerenciasMenciones);
					return;
				}
				
				// Filtrar usuarios
				mostrarSugerenciasMenciones();
			} else {
				// Ocultar menú cuando no hay @ al final
				if (document.getElementById('dropdown-menciones')) {
					document.getElementById('dropdown-menciones').style.display= "none";
				}
			}
		}
	});
	document.getElementById('inptContenidoAbmMensaje').addEventListener('blur', function() {
		setTimeout(function() {
			if (document.getElementById('dropdown-menciones')) {
				document.getElementById('dropdown-menciones').style.display= "none";
			}
		}, 150);
	});
	document.getElementById('inptContenidoAbmMensaje').addEventListener('keydown', function(e) {
		contadorLongitudMensaje = document.getElementById('inptContenidoAbmMensaje').innerText.length;
		
		// Teclas que siempre se permiten (borrar, flechas, etc.)
		const teclasPermitidas = [8, 46, 37, 38, 39, 40, 36, 35];
		if (teclasPermitidas.includes(e.keyCode) || e.ctrlKey || e.metaKey) {
			return;
		}

		// Permitir si hay texto seleccionado (se va a reemplazar)
		const seleccion = window.getSelection();
		if (seleccion.toString().length > 0) {
			return;
		}

		// Prevenir si se supera el límite
		if (contadorLongitudMensaje >= limiteCaracteresMensaje) {
			e.preventDefault();
    
			const textoPegado = (e.clipboardData || window.clipboardData).getData('text');
			const longitudActual = this.textContent.length;
			const seleccion = window.getSelection();
			const longitudSeleccion = seleccion.toString().length;
			
			const espacioDisponible = limiteCaracteresMensaje - (longitudActual - longitudSeleccion);

			if (espacioDisponible > 0) {
				const textoAInsertar = textoPegado.substring(0, espacioDisponible);
				document.execCommand('insertText', false, textoAInsertar);
			}
		}
	});
	document.getElementById('inptContenidoAbmMensaje').addEventListener('paste', function(e) {
    	e.preventDefault();

    	const textoPegado = (e.clipboardData || window.clipboardData).getData('text');
		const longitudActual = this.textContent.length;
		const seleccion = window.getSelection();
		const longitudSeleccion = seleccion.toString().length;
		
		const espacioDisponible = limiteCaracteresMensaje - (longitudActual - longitudSeleccion);

		if (espacioDisponible > 0) {
			const textoAInsertar = textoPegado.substring(0, espacioDisponible);
			document.execCommand('insertText', false, textoAInsertar);
		}
	});

	buscar_datos_del_usuario();
	obtenerUltimoLimiteCaja();
