function normalizarFotoUsuario(urlFoto) {
	var foto = (urlFoto || "").toString().trim();
	if (foto == "" || foto == "null" || foto == "undefined") {
		return "/GoodVentaAsisCap/iconos/sinperfil.png";
	}
	return foto;
}

