function fechaHoyFuncionarioRrhh() {
	if (typeof obtenerFechaHoyHorarioUsuario == "function") {
		return obtenerFechaHoyHorarioUsuario();
	}
	var hoy = new Date();
	var mes = hoy.getMonth() + 1;
	var dia = hoy.getDate();
	return hoy.getFullYear() + "-" + (mes < 10 ? "0" + mes : mes) + "-" + (dia < 10 ? "0" + dia : dia);
}

