function ver_vetana_informativa(titulo, detalle= "", tipo="") {
	document.getElementById('lbltitulomensajedetalle').style.display = "";
	titulo= titulo.toLowerCase();
	// Comprueba si es informacion ya predefinida o con error
	if (titulo.includes('error') && !tipo) {
		tipo= "error";
	}
	if (!detalle && !tipo) {
		detalle= titulo.toString();
		titulo= "Atencion";
		tipo= "advertencia";
	}
	document.getElementById('lbltitulomensaje').innerHTML = titulo;
	document.getElementById('lbltitulomensajedetalle').innerHTML = detalle.charAt(0).toUpperCase() + detalle.slice(1);
	
	// Oculta la ventana de detalles en caso de no tener informacion
	if (!detalle) {
		document.getElementById('lbltitulomensajedetalle').style.display = "none";
	}

	switch (tipo) {
		case 'error':
			document.getElementById('lbltitulomensaje').parentElement.style.backgroundColor= "rgb(245, 59, 59)";
			break;
		case 'info':
			document.getElementById('lbltitulomensaje').parentElement.style.backgroundColor= "#416c8f";
			break;
		case 'advertencia':
			document.getElementById('lbltitulomensaje').parentElement.style.backgroundColor= "#ff9f00";
			break;
		default:
			document.getElementById('lbltitulomensaje').parentElement.style.backgroundColor= '#646363';
			break;
	}
	
//	document.getElementById('div_principal_info').style.display = ''

	const toastLiveExample = document.getElementById('liveToast');
	const toastBootstrap = bootstrap.Toast.getOrCreateInstance(toastLiveExample);
	toastBootstrap.show();
}

async function ver_ventana_confirmacion(mensaje, titulo="Atencion") {
	return new Promise(function(resolve) {
		const modalEl = document.getElementById('confirmDialogGenerico');
		const tituloEl = document.getElementById('confirmDialogGenericoTitulo');
		const mensajeEl = document.getElementById('confirmDialogGenericoMensaje');
		const btnAceptar = document.getElementById('btnConfirmDialogGenericoAceptar');
		const btnCancelar = document.getElementById('btnConfirmDialogGenericoCancelar');
		const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
		let resuelto = false;

		tituloEl.innerHTML = titulo;
		mensajeEl.innerHTML = mensaje;

		function finalizar(valor) {
			if (resuelto) {
				return;
			}
			resuelto = true;
			btnAceptar.removeEventListener('click', aceptar);
			btnCancelar.removeEventListener('click', cancelar);
			modalEl.removeEventListener('hidden.bs.modal', cerrar);
			modal.hide();
			resolve(valor);
		}

		function aceptar() {
			finalizar(true);
		}

		function cancelar() {
			finalizar(false);
		}

		function cerrar() {
			finalizar(false);
		}

		btnAceptar.addEventListener('click', aceptar);
		btnCancelar.addEventListener('click', cancelar);
		modalEl.addEventListener('hidden.bs.modal', cerrar);
		modal.show();
	});
}

