var cajaCierreUenoUltimo = {};
function cajaCierreUenoConfig(destino) {
	if (destino === "consulta") {
		return {
			body: "divConsultaCajaUenoBody",
			operaciones: "lblConsultaCajaUenoOperaciones",
			cuotas: "lblConsultaCajaUenoCuotas",
			total: "lblConsultaCajaUenoTotal",
			vacio: "No se registraron cobros conciliados con Ueno Bank durante este cierre."
		};
	}
	return {
		body: "divCajaCierreUenoBody",
		operaciones: "lblCajaCierreUenoOperaciones",
		cuotas: "lblCajaCierreUenoCuotas",
		total: "lblCajaCierreUenoTotal",
		vacio: "No se registraron cobros conciliados con Ueno Bank durante este cierre."
	};
}

function cajaCierreUenoSetTexto(id, valor) {
	const elemento = document.getElementById(id);
	if (elemento) {
		elemento.innerHTML = valor;
	}
}

function cajaCierreUenoClaseEstado(estado) {
	estado = (estado || "").toString().toLowerCase();
	if (estado.indexOf("parcial") >= 0 || estado.indexOf("pendiente") >= 0) {
		return "is-warning";
	}
	if (estado.indexOf("concili") >= 0) {
		return "is-ok";
	}
	if (estado.indexOf("anul") >= 0 || estado.indexOf("rechaz") >= 0 || estado.indexOf("revers") >= 0) {
		return "is-danger";
	}
	return "is-muted";
}

function cajaCierreUenoLimpiar(destino, mensaje) {
	const config = cajaCierreUenoConfig(destino);
	cajaCierreUenoSetTexto(config.operaciones, "0");
	cajaCierreUenoSetTexto(config.cuotas, "0");
	cajaCierreUenoSetTexto(config.total, "0 Gs.");
	cajaCierreUenoSetTexto(config.body, "<div class='caja-ueno-empty'>" + cajaCierreTextoSeguro(mensaje || config.vacio) + "</div>");
}

function cajaCierreBuscarUenoCierre(idArqueo, destino) {
	destino = destino || "cierre";
	const config = cajaCierreUenoConfig(destino);
	if (!document.getElementById(config.body)) {
		return;
	}
	if (!idArqueo) {
		cajaCierreUenoLimpiar(destino, destino === "consulta" ? "Selecciona una caja para ver sus conciliaciones Ueno." : config.vacio);
		return;
	}
	cajaCierreUenoSetTexto(config.body, "<div class='caja-ueno-empty'>Cargando conciliaciones Ueno...</div>");
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"idArqeoFk": idArqueo,
		"funt": "buscar_conciliaciones_ueno_cierre"
	};
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmaperturacierrecaja.php",
		type: "post",
		error: function (jqXHR, textstatus) {
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
			cajaCierreUenoSetTexto(config.body, "<div class='caja-ueno-empty caja-ueno-empty--alert'>No se pudo cargar el control Ueno.</div>");
		},
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				var respuesta = respuestaJqueryAjax(datos["1"]);
				if (respuesta == true) {
					cajaCierreRenderUenoCierre(datos, destino);
				} else if (datos["1"] == "NI") {
					cajaCierreUenoSetTexto(config.body, "<div class='caja-ueno-empty caja-ueno-empty--alert'>No tiene permiso para ver estas conciliaciones.</div>");
				} else {
					cajaCierreUenoSetTexto(config.body, "<div class='caja-ueno-empty caja-ueno-empty--alert'>" + cajaCierreTextoSeguro(datos["2"] || "No se pudo cargar el control Ueno.") + "</div>");
				}
			} catch (error) {
				cajaCierreUenoSetTexto(config.body, "<div class='caja-ueno-empty caja-ueno-empty--alert'>No se pudo interpretar el control Ueno.</div>");
				var titulo = "Error: " + error + " \r\n Consola: " + responseText;
				GuardarArchivosLog(titulo);
			}
		}
	});
}

function cajaCierreRenderUenoCierre(datos, destino) {
	const config = cajaCierreUenoConfig(destino);
	const resumen = datos.resumen || {};
	const filas = datos.filas || [];
	cajaCierreUenoUltimo[destino || "cierre"] = datos;
	cajaCierreUenoSetTexto(config.operaciones, cajaCierreTextoSeguro(resumen.operaciones || 0));
	cajaCierreUenoSetTexto(config.cuotas, cajaCierreTextoSeguro(resumen.cuotas || 0));
	cajaCierreUenoSetTexto(config.total, cajaCierreTextoSeguro(resumen.total_aplicado_texto || "0") + " Gs.");

	if (filas.length === 0) {
		cajaCierreUenoSetTexto(config.body, "<div class='caja-ueno-empty'>" + cajaCierreTextoSeguro(config.vacio) + "</div>");
		return;
	}

	var html = ""
		+ "<div class='caja-ueno-table'>"
		+ "<div class='caja-ueno-row caja-ueno-row--head'>"
		+ "<span>Conciliacion</span>"
		+ "<span>Comprobante</span>"
		+ "<span>Paciente</span>"
		+ "<span>Venta / alias</span>"
		+ "<span>Cuota</span>"
		+ "<span>Monto cuota</span>"
		+ "<span>Aplicado</span>"
		+ "<span>Tipo</span>"
		+ "<span>Usuario</span>"
		+ "<span>Estado</span>"
		+ "</div>";
	filas.forEach(function (fila) {
		const ventaAlias = (fila.venta || "-") + (fila.alias_venta ? " / " + fila.alias_venta : "");
		const paciente = (fila.paciente || "Sin paciente") + (fila.cedula ? " - " + fila.cedula : "");
		const estado = fila.estado || "-";
		html += "<div class='caja-ueno-row'>"
			+ "<span data-label='Conciliacion'>" + cajaCierreTextoSeguro(fila.fecha_conciliacion || "-") + "</span>"
			+ "<span data-label='Comprobante'>" + cajaCierreTextoSeguro(fila.comprobante || "-") + "</span>"
			+ "<span data-label='Paciente'>" + cajaCierreTextoSeguro(paciente) + "</span>"
			+ "<span data-label='Venta / alias'>" + cajaCierreTextoSeguro(ventaAlias) + "</span>"
			+ "<span data-label='Cuota'>" + cajaCierreTextoSeguro(fila.cuota || "-") + "</span>"
			+ "<span data-label='Monto cuota' class='caja-ueno-money'>" + cajaCierreTextoSeguro(fila.monto_cuota_texto || "0") + " Gs.</span>"
			+ "<span data-label='Aplicado' class='caja-ueno-money'>" + cajaCierreTextoSeguro(fila.monto_aplicado_texto || "0") + " Gs.</span>"
			+ "<span data-label='Tipo'>" + cajaCierreTextoSeguro(fila.tipo_aplicacion || "-") + "</span>"
			+ "<span data-label='Usuario'>" + cajaCierreTextoSeguro(fila.usuario_conciliador || "-") + "</span>"
			+ "<span data-label='Estado'><b class='caja-ueno-status " + cajaCierreUenoClaseEstado(estado) + "'>" + cajaCierreTextoSeguro(estado) + "</b></span>"
			+ "</div>";
	});
	html += "</div>";
	cajaCierreUenoSetTexto(config.body, html);
}

function obtenerMontoNumericoAperturaCierreCaja(id) {
	const elemento = document.getElementById(id);
	if (!elemento) {
		return 0;
	}
	const valor = (elemento.value || "0").toString().replace(/\./g, '').replace(',', '.');
	const numero = Number(valor);
	return isNaN(numero) ? 0 : numero;
}

function formatearMontoAperturaCierreCaja(valor) {
	valor = Number(valor || 0);
	return valor.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

function cajaCierreEsperadoBackend() {
	if (cajaCierreResumenMedios && cajaCierreResumenMedios.efectivo_esperado !== undefined && cajaCierreResumenMedios.efectivo_esperado !== null && cajaCierreResumenMedios.efectivo_esperado !== "") {
		const valor = cajaCierreResumenMedios.efectivo_esperado.toString().replace(/\./g, '').replace(',', '.');
		const numero = Number(valor);
		return isNaN(numero) ? 0 : numero;
	}
	return null;
}

function actualizarResumenEsperadoAperturaCierreCaja() {
	const montoApertura = obtenerMontoNumericoAperturaCierreCaja('inptMontoAperturaCierreCaja');
	const totalRecaudado = obtenerMontoNumericoAperturaCierreCaja('inptMontoRecaudadoCierreCaja');
	const uenoConciliado = cajaCierreMedio('total_transferencias_conciliadas');
	const esperadoBackend = cajaCierreEsperadoBackend();
	const resumenInicial = document.getElementById('inptResumenInicialAperturaCierre');
	const resumenMontoApertura = document.getElementById('inptMontoAperturaCierreCajaResumen');
	const resumenUeno = document.getElementById('inptUenoConciliadoCierreCaja');
	const resumenTotal = document.getElementById('inptResumenTotalAperturaCierre');

	if (resumenInicial) {
		resumenInicial.value = formatearMontoAperturaCierreCaja(montoApertura);
	}
	if (resumenMontoApertura) {
		resumenMontoApertura.value = formatearMontoAperturaCierreCaja(montoApertura);
	}
	if (resumenUeno) {
		resumenUeno.value = formatearMontoAperturaCierreCaja(uenoConciliado);
	}
	if (resumenTotal) {
		resumenTotal.value = formatearMontoAperturaCierreCaja(esperadoBackend !== null ? esperadoBackend : (montoApertura + totalRecaudado));
	}
	cajaCierreActualizarResumenSeguro();
}

function cajaCierreElemento(id) {
	return document.getElementById(id);
}

function cajaCierreSetTexto(id, valor) {
	const elemento = cajaCierreElemento(id);
	if (elemento) {
		elemento.innerHTML = valor;
	}
}

function cajaCierreFormatoGs(valor) {
	return formatearMontoAperturaCierreCaja(Number(valor || 0)) + " Gs.";
}

function cajaCierreCantidad(id) {
	const elemento = cajaCierreElemento(id);
	if (!elemento) {
		return 0;
	}
	let valor = parseInt((elemento.value || "0").toString().replace(/[^\d-]/g, ''), 10);
	if (isNaN(valor) || valor < 0) {
		valor = 0;
	}
	if (elemento.value !== valor.toString()) {
		elemento.value = valor;
	}
	return valor;
}

function cajaCierreDenominaciones() {
	const filas = [
		{ denominacion: 500, id: 'inptMontoCierreCaja5', subtotal: 'lblCajaDenomSub500' },
		{ denominacion: 1000, id: 'inptMontoCierreCaja10', subtotal: 'lblCajaDenomSub1000' },
		{ denominacion: 2000, id: 'inptMontoCierreCaja20', subtotal: 'lblCajaDenomSub2000' },
		{ denominacion: 5000, id: 'inptMontoCierreCaja50', subtotal: 'lblCajaDenomSub5000' },
		{ denominacion: 10000, id: 'inptMontoCierreCaja100', subtotal: 'lblCajaDenomSub10000' },
		{ denominacion: 20000, id: 'inptMontoCierreCaja200', subtotal: 'lblCajaDenomSub20000' },
		{ denominacion: 50000, id: 'inptMontoCierreCaja500', subtotal: 'lblCajaDenomSub50000' },
		{ denominacion: 100000, id: 'inptMontoCierreCaja1000', subtotal: 'lblCajaDenomSub100000' }
	];
	return filas.map(function (fila) {
		const cantidad = cajaCierreCantidad(fila.id);
		return {
			denominacion: fila.denominacion,
			cantidad: cantidad,
			subtotal: cantidad * fila.denominacion,
			subtotalId: fila.subtotal
		};
	});
}

function cajaCierreTotalContado() {
	return cajaCierreDenominaciones().reduce(function (total, fila) {
		return total + fila.subtotal;
	}, 0);
}

function cajaCierreEsperado() {
	return obtenerMontoNumericoAperturaCierreCaja('inptResumenTotalAperturaCierre');
}

function cajaCierreDiferencia() {
	return cajaCierreTotalContado() - cajaCierreEsperado();
}

function cajaCierreEstadoVisual() {
	return cajaCierreDiferencia() === 0 ? "Caja cuadrada" : "Caja con diferencia";
}

function cajaCierreEstadoRevision() {
	const diferencia = Math.abs(cajaCierreDiferencia());
	if (diferencia === 0) {
		return "Cerrada";
	}
	if (diferencia <= 5000) {
		return "Diferencia menor";
	}
	if (diferencia <= 50000) {
		return "Pendiente de revision";
	}
	return "Pendiente de revision urgente";
}

function cajaCierreMedio(nombre) {
	if (!cajaCierreResumenMedios || cajaCierreResumenMedios[nombre] === undefined) {
		return 0;
	}
	return Number(cajaCierreResumenMedios[nombre] || 0);
}

function cajaCierreTieneFoto() {
	const input = cajaCierreElemento('inptCajaCierreFoto');
	return !!(input && input.files && input.files.length > 0);
}

function cajaCierreActualizarResumenSeguro() {
	if (!cajaCierreElemento('divCajaCierreWizard')) {
		return;
	}
	const denominaciones = cajaCierreDenominaciones();
	denominaciones.forEach(function (fila) {
		cajaCierreSetTexto(fila.subtotalId, cajaCierreFormatoGs(fila.subtotal));
	});

	const totalContado = cajaCierreTotalContado();
	const esperado = cajaCierreEsperado();
	const diferencia = totalContado - esperado;
	const diferenciaAbs = Math.abs(diferencia);
	const estado = cajaCierreEstadoVisual();
	const estadoRevision = cajaCierreEstadoRevision();
	const transferencia = cajaCierreMedio('total_transferencias');
	const transferenciaConciliada = cajaCierreMedio('total_transferencias_conciliadas');
	const tarjetas = cajaCierreMedio('total_tarjetas');
	const billeterasOtros = cajaCierreMedio('total_billeteras') + cajaCierreMedio('total_otros');

	cajaCierreSetTexto('lblCajaCierreTotalConteo', cajaCierreFormatoGs(totalContado));
	cajaCierreSetTexto('lblCajaCierreEsperado', cajaCierreFormatoGs(esperado));
	cajaCierreSetTexto('lblCajaCierreContado', cajaCierreFormatoGs(totalContado));
	cajaCierreSetTexto('lblCajaCierreDiferencia', cajaCierreFormatoGs(diferencia));
	cajaCierreSetTexto('lblCajaCierreEstado', estado + " / " + estadoRevision);
	cajaCierreSetTexto('lblCajaCierreTransferencias', cajaCierreFormatoGs(transferencia));
	cajaCierreSetTexto('lblCajaCierreTransferenciasConciliadas', cajaCierreFormatoGs(transferenciaConciliada));
	cajaCierreSetTexto('lblCajaCierreTarjetas', cajaCierreFormatoGs(tarjetas));
	cajaCierreSetTexto('lblCajaCierreBilleteras', cajaCierreFormatoGs(billeterasOtros));
	cajaCierreSetTexto('txtCajaCierreMensajeDiferencia', diferencia === 0 ? "La caja cuadra. No se requiere observacion." : "Se detecto una diferencia de " + cajaCierreFormatoGs(diferencia) + ". Para cerrar la caja, selecciona un motivo.");

	cajaCierreSetTexto('lblCajaCierreLoteFinal', cajaCierreLoteActual || loteCaja || "-");
	cajaCierreSetTexto('lblCajaCierreCajeraFinal', cajaCierreElemento('inptcajeroAperturaCierreCaja') ? cajaCierreElemento('inptcajeroAperturaCierreCaja').value : "-");
	cajaCierreSetTexto('lblCajaCierreEsperadoFinal', cajaCierreFormatoGs(esperado));
	cajaCierreSetTexto('lblCajaCierreContadoFinal', cajaCierreFormatoGs(totalContado));
	cajaCierreSetTexto('lblCajaCierreDiferenciaFinal', cajaCierreFormatoGs(diferencia));
	cajaCierreSetTexto('lblCajaCierreFotoFinal', cajaCierreTieneFoto() ? "Si" : "No");
	cajaCierreSetTexto('lblCajaCierreFirmaFinal', cajaCierreFirmaLista ? "Si" : "No");
	cajaCierreSetTexto('lblCajaCierreEstadoFinal', estado + " / " + estadoRevision);

	const boxDiferencia = cajaCierreElemento('boxCajaCierreDiferencia');
	if (boxDiferencia) {
		boxDiferencia.classList.remove('is-ok', 'is-alert', 'is-danger');
		boxDiferencia.classList.add(diferenciaAbs === 0 ? 'is-ok' : (diferenciaAbs <= 50000 ? 'is-alert' : 'is-danger'));
	}
	const btnObservacion = cajaCierreElemento('btnCajaCierrePaso4');
	if (btnObservacion) {
		btnObservacion.style.display = diferencia === 0 ? 'none' : '';
	}
	const camposObservacion = cajaCierreElemento('divCajaCierreObservacionCampos');
	if (camposObservacion) {
		camposObservacion.style.display = diferencia === 0 ? 'none' : 'grid';
	}
}

