var idAbmInsumos = "";
var filaAbmInsumos = "";
var productosDisponiblesAbmInsumos = [];
var productosDisponiblesAbmInsumosCargados = false;
var productosDisponiblesAbmInsumosCargando = false;
var callbacksProductosDisponiblesAbmInsumos = [];
var productosSeleccionadosAbmInsumos = {};
var abmInsumosFilasPorId = {};
var dashboardInsumosStockFilaPendiente = null;
var variantesAbmInsumos = [];
var codigoReposicionInsumoSeleccionada = "";
var temporizadorBusquedaHilosReposicionInsumos = null;
var solicitudBusquedaHilosReposicionInsumos = 0;

function verTabInsumos(tab) {
	var tabs = ["abm", "stock", "movimientos", "alertas"];
	for (var i = 0; i < tabs.length; i++) {
		var contenido = document.getElementById("tabInsumos" + tabs[i].charAt(0).toUpperCase() + tabs[i].slice(1));
		var boton = document.getElementById("btnTabInsumos" + tabs[i].charAt(0).toUpperCase() + tabs[i].slice(1));
		if (contenido) {
			contenido.classList.toggle("activo", tabs[i] == tab);
		}
		if (boton) {
			boton.classList.toggle("activo", tabs[i] == tab);
		}
	}
	if (tab == "stock") {
		cargarCatalogosDashboardInsumos(function () { buscarDashboardInsumosStock(); });
	}
	if (tab == "movimientos") {
		cargarCatalogosDashboardInsumos(function () {
			prepararReposicionInsumos();
			listarReposicionesInsumos();
		});
	}
	if (tab == "alertas") {
		listarAlertasStockInsumos();
	}
}

function toggleHistorialMovimientosInsumos(mostrar) {
	var contenedor = document.getElementById("contenedorHistorialMovimientosInsumos");
	var boton = document.getElementById("btnToggleHistorialMovimientosInsumos");
	if (!contenedor) {
		return;
	}
	var visible = contenedor.style.display !== "none";
	var nuevoVisible = typeof mostrar === "boolean" ? mostrar : !visible;
	contenedor.style.display = nuevoVisible ? "" : "none";
	if (boton) {
		boton.value = nuevoVisible ? "Ocultar historial" : "Ver historial";
	}
}

function actualizarEstadoBotonPdfMovimientoInsumos() {
	var botonPdf = document.getElementById("btnGenerarPdfMovimientoInsumos");
	if (botonPdf) {
		botonPdf.disabled = codigoReposicionInsumoSeleccionada == "";
	}
}

function verCerrarVentanaAbmInsumos(d, l) {
	verTabInsumos("abm");
	if (d == "1") {
		if (l == "1") {
			limpiarCamposAbmInsumos();
		}
		$("div[id=divAbmInsumos2]").fadeIn(250);
		document.getElementById("divAbmInsumos1").style.display = "none";
		cargarProductosDisponiblesAbmInsumos(function () {
			renderProductosInsumoSeleccionables();
		});
	} else {
		$("div[id=divAbmInsumos1]").fadeIn(250);
		document.getElementById("divAbmInsumos2").style.display = "none";
	}
}

function limpiarCamposAbmInsumos() {
	var ids = ["inptNombreInsumo", "inptDescripcionInsumo", "inptStockInsumo", "inptStockMinimoInsumo", "inptUnidadInsumo", "inptRegistroSeleccInsumos"];
	for (var i = 0; i < ids.length; i++) {
		if (document.getElementById(ids[i])) {
			document.getElementById(ids[i]).value = "";
		}
	}
	if (document.getElementById("inptEstadoInsumo")) {
		document.getElementById("inptEstadoInsumo").value = "Activo";
	}
	if (document.getElementById("inptStockMinimoInsumo")) {
		document.getElementById("inptStockMinimoInsumo").value = "0";
	}
	if (document.getElementById("btnAbmInsumosGuardar")) {
		document.getElementById("btnAbmInsumosGuardar").value = "Guardar datos";
	}
	if (document.getElementById("divProductosInsumo")) {
		document.getElementById("divProductosInsumo").innerHTML = "";
	}
	if (document.getElementById("inptBuscarProductoInsumo")) {
		document.getElementById("inptBuscarProductoInsumo").value = "";
	}
	productosSeleccionadosAbmInsumos = {};
	variantesAbmInsumos = [];
	if (document.getElementById("chkInsumoTieneVariantes")) {
		document.getElementById("chkInsumoTieneVariantes").checked = false;
	}
	if (document.getElementById("inptTipoVarianteInsumo")) {
		document.getElementById("inptTipoVarianteInsumo").value = "Tamano";
	}
	toggleVariantesInsumo();
	idAbmInsumos = "";
	filaAbmInsumos = "";
}

function ObtenerdatosAbmInsumos(datostr) {
	$("tr[id=tbSelecRegistroInsumos]").each(function (i, td) {
		td.className = "";
	});
	datostr.className = "tableRegistroSelec";
	filaAbmInsumos = datostr;
	idAbmInsumos = obtenerTextoCeldaAbmInsumos(datostr, "td_id");
	if (document.getElementById("inptRegistroSeleccInsumos")) {
		document.getElementById("inptRegistroSeleccInsumos").value = obtenerTextoCeldaAbmInsumos(datostr, "td_datos_1");
	}
}

function verVentanaEditarAbmInsumos() {
	if (idAbmInsumos == "") {
		ver_vetana_informativa("FALTO SELECCIONAR UN REGISTRO");
		return;
	}
	var filaDatos = abmInsumosFilasPorId[String(idAbmInsumos)] || {};
	document.getElementById("inptNombreInsumo").value = filaDatos.nombre || obtenerTextoCeldaAbmInsumos(filaAbmInsumos, "td_datos_1");
	document.getElementById("inptDescripcionInsumo").value = obtenerTextoCeldaAbmInsumos(filaAbmInsumos, "td_datos_2");
	document.getElementById("inptStockInsumo").value = obtenerTextoCeldaAbmInsumos(filaAbmInsumos, "td_datos_3");
	document.getElementById("inptStockMinimoInsumo").value = obtenerTextoCeldaAbmInsumos(filaAbmInsumos, "td_datos_4");
	document.getElementById("inptUnidadInsumo").value = obtenerTextoCeldaAbmInsumos(filaAbmInsumos, "td_datos_5");
	document.getElementById("inptEstadoInsumo").value = obtenerTextoCeldaAbmInsumos(filaAbmInsumos, "td_datos_6");
	variantesAbmInsumos = filaDatos.variantes ? JSON.parse(JSON.stringify(filaDatos.variantes)) : [];
	if (document.getElementById("chkInsumoTieneVariantes")) {
		document.getElementById("chkInsumoTieneVariantes").checked = String(filaDatos.tiene_variantes || "0") == "1";
	}
	if (document.getElementById("inptTipoVarianteInsumo")) {
		var tipoVariante = filaDatos.tipo_variante || "Tamano";
		if (tipoVariante == "Tamaño" || tipoVariante == "Tamaño") {
			tipoVariante = "Tamano";
		}
		if (tipoVariante == "Presentación" || tipoVariante == "Presentación") {
			tipoVariante = "Presentacion";
		}
		document.getElementById("inptTipoVarianteInsumo").value = tipoVariante;
	}
	toggleVariantesInsumo();
	document.getElementById("btnAbmInsumosGuardar").value = "Editar datos";
	productosSeleccionadosAbmInsumos = {};
	verCerrarVentanaAbmInsumos("1", "2");
	cargarProductosAsociadosAbmInsumos(idAbmInsumos);
}

function editarAbmInsumosDesdeFila(idInsumo, event) {
	if (event) {
		event.stopPropagation();
	}
	var fila = document.querySelector('#table_abm_Insumos tr[data-id-insumo="' + String(idInsumo) + '"]');
	if (fila) {
		ObtenerdatosAbmInsumos(fila);
	}
	idAbmInsumos = String(idInsumo || "");
	verVentanaEditarAbmInsumos();
}

function obtenerTextoCeldaAbmInsumos(fila, idCelda) {
	var texto = $(fila).children('td[id="' + idCelda + '"]').text();
	return limpiarTextoHtmlAbmInsumos(texto);
}

function limpiarTextoHtmlAbmInsumos(valor) {
	var texto = String(valor == null ? "" : valor);
	var anterior = "";
	while (texto != anterior && /&lt;|&gt;|<[^>]*>/i.test(texto)) {
		anterior = texto;
		texto = $("<textarea/>").html(texto).text();
		texto = texto.replace(/<[^>]*>/g, "");
	}
	return texto.trim();
}

function toggleVariantesInsumo() {
	var activo = document.getElementById("chkInsumoTieneVariantes") && document.getElementById("chkInsumoTieneVariantes").checked == true;
	if (document.getElementById("bloqueVariantesInsumo")) {
		document.getElementById("bloqueVariantesInsumo").classList.toggle("insumos-form-section--oculta", !activo);
	}
	if (document.getElementById("divVariantesInsumo")) {
		document.getElementById("divVariantesInsumo").style.display = activo ? "" : "none";
	}
	if (document.getElementById("inptStockInsumo")) {
		document.getElementById("inptStockInsumo").readOnly = activo;
	}
	if (document.getElementById("inptStockMinimoInsumo")) {
		document.getElementById("inptStockMinimoInsumo").readOnly = activo;
	}
	if (activo && variantesAbmInsumos.length == 0) {
		agregarVarianteInsumo();
	}
	renderVariantesInsumo();
}

function agregarVarianteInsumo(variante) {
	variantesAbmInsumos.push(variante || { id_variante: 0, nombre_variante: "", stock: 0, stock_minimo: 0, estado: "Activo" });
	renderVariantesInsumo();
}

function quitarVarianteInsumo(indice) {
	variantesAbmInsumos.splice(indice, 1);
	renderVariantesInsumo();
}

function actualizarVarianteInsumo(indice, campo, valor) {
	if (!variantesAbmInsumos[indice]) {
		return;
	}
	variantesAbmInsumos[indice][campo] = valor;
	recalcularStockPadreDesdeVariantes();
}

function recalcularStockPadreDesdeVariantes() {
	if (!document.getElementById("chkInsumoTieneVariantes") || document.getElementById("chkInsumoTieneVariantes").checked != true) {
		return;
	}
	var stock = 0;
	var minimo = 0;
	for (var i = 0; i < variantesAbmInsumos.length; i++) {
		if (variantesAbmInsumos[i].estado == "Activo") {
			stock += Number(variantesAbmInsumos[i].stock || 0);
			minimo += Number(variantesAbmInsumos[i].stock_minimo || 0);
		}
	}
	var stockTexto = stock.toFixed(3).replace(/\.?0+$/, "");
	var minimoTexto = minimo.toFixed(3).replace(/\.?0+$/, "");
	document.getElementById("inptStockInsumo").value = stockTexto == "" ? "0" : stockTexto;
	document.getElementById("inptStockMinimoInsumo").value = minimoTexto == "" ? "0" : minimoTexto;
}

function renderVariantesInsumo() {
	var contenedor = document.getElementById("tableVariantesInsumo");
	if (!contenedor) {
		return;
	}
	var html = "";
	for (var i = 0; i < variantesAbmInsumos.length; i++) {
		var variante = variantesAbmInsumos[i];
		html += "<table class='tableRegistroSearch' border='1' cellspacing='1' cellpadding='5' style='width:100%'><tr>";
		html += "<td class='tdRegistroSearch' style='width:34%'><input class='inputText' type='text' value='" + escaparHtmlAbmInsumos(variante.nombre_variante || "") + "' oninput='actualizarVarianteInsumo(" + i + ", \"nombre_variante\", this.value)' style='width:100%;height:30px'></td>";
		html += "<td class='tdRegistroSearch' style='width:18%'><input class='inputText' type='number' min='0' step='any' value='" + escaparHtmlAbmInsumos(variante.stock || 0) + "' oninput='actualizarVarianteInsumo(" + i + ", \"stock\", this.value)' style='width:100%;height:30px'></td>";
		html += "<td class='tdRegistroSearch' style='width:18%'><input class='inputText' type='number' min='0' step='any' value='" + escaparHtmlAbmInsumos(variante.stock_minimo || 0) + "' oninput='actualizarVarianteInsumo(" + i + ", \"stock_minimo\", this.value)' style='width:100%;height:30px'></td>";
		html += "<td class='tdRegistroSearch' style='width:20%'><select class='inputSelect' onchange='actualizarVarianteInsumo(" + i + ", \"estado\", this.value)' style='width:100%;height:30px'><option value='Activo' " + (variante.estado != "Inactivo" ? "selected" : "") + ">Activo</option><option value='Inactivo' " + (variante.estado == "Inactivo" ? "selected" : "") + ">Inactivo</option></select></td>";
		html += "<td class='tdRegistroSearch' style='width:10%;text-align:center'><input type='button' class='btn2' value='X' onclick='quitarVarianteInsumo(" + i + ")' style='width:34px;height:26px;padding:0;background:#dc2626;border-radius:7px;'></td>";
		html += "</tr></table>";
	}
	contenedor.innerHTML = html || "<p class='pTituloC' style='padding:10px;text-align:center;color:#607080'>Sin variantes cargadas.</p>";
	recalcularStockPadreDesdeVariantes();
}

function validarVariantesAbmInsumos() {
	if (!document.getElementById("chkInsumoTieneVariantes") || document.getElementById("chkInsumoTieneVariantes").checked != true) {
		return true;
	}
	var nombres = {};
	var activas = 0;
	for (var i = 0; i < variantesAbmInsumos.length; i++) {
		var nombre = String(variantesAbmInsumos[i].nombre_variante || "").trim();
		if (nombre == "") {
			ver_vetana_informativa("FALTA INGRESAR EL NOMBRE DE UNA VARIANTE");
			return false;
		}
		var clave = nombre.toLowerCase();
		if (nombres[clave]) {
			ver_vetana_informativa("NO SE PERMITEN VARIANTES DUPLICADAS");
			return false;
		}
		nombres[clave] = true;
		if (variantesAbmInsumos[i].estado == "Activo") {
			activas++;
		}
	}
	if (activas == 0) {
		ver_vetana_informativa("DEBE CARGAR AL MENOS UNA VARIANTE ACTIVA");
		return false;
	}
	return true;
}

function verificarCamposAbmInsumos() {
	var nombre = document.getElementById("inptNombreInsumo").value;
	if (nombre == "") {
		document.getElementById("inptNombreInsumo").focus();
		ver_vetana_informativa("FALTO INGRESAR EL NOMBRE DEL INSUMO");
		return;
	}
	var descripcion = document.getElementById("inptDescripcionInsumo").value;
	if (descripcion == "") {
		document.getElementById("inptDescripcionInsumo").focus();
		ver_vetana_informativa("FALTO SELECCIONAR LA DESCRIPCION DEL INSUMO");
		return;
	}
	if (validarVariantesAbmInsumos() == false) {
		return;
	}
	var accion = idAbmInsumos != "" ? "editar" : "nuevo";
	abmInsumos(accion);
}

function abmInsumos(accion) {
	verCerrarEfectoCargando("1");
	var datos = new FormData();
	obtener_datos_user();
	datos.append("useru", userid);
	datos.append("passu", passuser);
	datos.append("navegador", navegador);
	datos.append("funt", accion);
	datos.append("id_insumo", idAbmInsumos);
	datos.append("nombre", document.getElementById("inptNombreInsumo").value);
	datos.append("descripcion", document.getElementById("inptDescripcionInsumo").value);
	datos.append("cant_stock", document.getElementById("inptStockInsumo").value);
	datos.append("stock_minimo", document.getElementById("inptStockMinimoInsumo").value);
	datos.append("unidad_medida", document.getElementById("inptUnidadInsumo").value);
	datos.append("estado", document.getElementById("inptEstadoInsumo").value);
	datos.append("tiene_variantes", document.getElementById("chkInsumoTieneVariantes") && document.getElementById("chkInsumoTieneVariantes").checked ? "1" : "0");
	datos.append("tipo_variante", document.getElementById("inptTipoVarianteInsumo") ? document.getElementById("inptTipoVarianteInsumo").value : "");
	datos.append("variantes", JSON.stringify(variantesAbmInsumos));
	$("#divProductosInsumo .insumo-producto-check:checked").each(function () {
		var codProducto = $(this).val();
		var cantidad = $(this).closest(".insumo-producto-card").find(".insumo-producto-cantidad").val();
		productosSeleccionadosAbmInsumos[String(codProducto)] = cantidad || 1;
	});
	for (var codProducto in productosSeleccionadosAbmInsumos) {
		if (productosSeleccionadosAbmInsumos.hasOwnProperty(codProducto)) {
			datos.append("productos[]", codProducto);
			datos.append("cantidades[]", productosSeleccionadosAbmInsumos[codProducto] || 1);
		}
	}
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		cache: false,
		contentType: false,
		processData: false,
		error: function (jqXHR, textstatus, errorThrowm) {
			verCerrarEfectoCargando("");
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
		},
		success: function (responseText) {
			verCerrarEfectoCargando("");
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) == true) {
					ver_vetana_informativa("DATOS CARGADO CORRECTAMENTE...");
					limpiarCamposAbmInsumos();
					verCerrarVentanaAbmInsumos("2", "");
					buscarAbmInsumos();
				} else if (datos["mensaje"]) {
					ver_vetana_informativa(datos["mensaje"], "", "error");
				}
			} catch (error) {
				ver_vetana_informativa("LO SENTIMOS HA OCURRIDO UN ERROR");
				GuardarArchivosLog("Error: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function buscarAbmInsumos() {
	var buscar = document.getElementById("inptBuscarAbmInsumos").value;
	var estado = obtenerEstadoBuscarAbmInsumos();
	document.getElementById("table_abm_Insumos").innerHTML = paginacargando;
	idAbmInsumos = "";
	filaAbmInsumos = "";
	if (document.getElementById("inptRegistroSeleccInsumos")) {
		document.getElementById("inptRegistroSeleccInsumos").value = "";
	}
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"codigo": /^\d+$/.test(buscar) ? buscar : "",
		"nombre": /^\d+$/.test(buscar) ? "" : buscar,
		"estado": estado,
		"funt": "buscar"
	};
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		error: function (jqXHR, textstatus, errorThrowm) {
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
			document.getElementById("table_abm_Insumos").innerHTML = "";
		},
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) == true) {
					renderTablaAbmInsumos(datos.filas || []);
					document.getElementById("inptTotalRegistroInsumos").value = datos["3"] || 0;
				}
			} catch (error) {
				document.getElementById("table_abm_Insumos").innerHTML = "";
				ver_vetana_informativa("LO SENTIMOS HA OCURRIDO UN ERROR");
				GuardarArchivosLog("Error: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function obtenerEstadoBuscarAbmInsumos() {
	var seleccionado = document.querySelector('input[name="estadoBuscarInsumos"]:checked');
	if (seleccionado) {
		return seleccionado.value;
	}
	if (document.getElementById("inptEstadoBuscarInsumos2") && document.getElementById("inptEstadoBuscarInsumos2").checked == true) {
		return "Inactivo";
	}
	return "Activo";
}

function renderTablaAbmInsumos(filas) {
	var html = "";
	var resumen = { activos: 0, inactivos: 0, variantes: 0, bajo: 0 };
	abmInsumosFilasPorId = {};
	for (var i = 0; i < filas.length; i++) {
		var fila = filas[i];
		abmInsumosFilasPorId[String(fila.id_insumo)] = fila;
		var estado = fila.estado_texto || (fila.estado == "1" ? "Activo" : "Inactivo");
		var variantesTexto = obtenerResumenVariantesAbmInsumos(fila);
		var esInactivo = String(estado).toLowerCase() == "inactivo";
		var estadoStock = esInactivo ? { texto: "Inactivo", clase: "inactivo" } : obtenerEstadoStockAbmInsumos(fila);
		if (esInactivo) {
			resumen.inactivos++;
		} else {
			resumen.activos++;
		}
		if (String(fila.tiene_variantes || "0") == "1") {
			resumen.variantes++;
		}
		if (estadoStock.clase != "ok" && !esInactivo) {
			resumen.bajo++;
		}
		html += "<table class='tableRegistroSearch insumos-abm-table' border='1' cellspacing='0' cellpadding='0' style='width:100%'>";
		html += "<tr id='tbSelecRegistroInsumos' class='insumos-row-editable' data-id-insumo='" + escaparHtmlAbmInsumos(fila.id_insumo) + "' onclick='editarAbmInsumosDesdeFila(\"" + escaparHtmlAbmInsumos(fila.id_insumo) + "\", event)'>";
		html += "<td id='td_id' style='width:7%' class='tdRegistroSearch'>" + escaparHtmlAbmInsumos(fila.id_insumo) + "</td>";
		html += "<td id='td_datos_1' style='width:27%' class='tdRegistroSearch'><div class='insumo-cell-title'>" + escaparHtmlAbmInsumos(fila.nombre || "") + "</div>" + variantesTexto + "</td>";
		html += "<td id='td_datos_2' style='width:22%' class='tdRegistroSearch'>" + escaparHtmlAbmInsumos(fila.descripcion) + "</td>";
		html += "<td id='td_datos_3' style='width:9%;text-align:center' class='tdRegistroSearch'>" + escaparHtmlAbmInsumos(fila.cant_stock) + "</td>";
		html += "<td id='td_datos_4' style='width:8%;text-align:center' class='tdRegistroSearch'>" + escaparHtmlAbmInsumos(fila.stock_minimo || 0) + "</td>";
		html += "<td id='td_datos_5' style='width:8%' class='tdRegistroSearch'>" + escaparHtmlAbmInsumos(fila.unidad_medida) + "</td>";
		html += "<td style='width:10%;text-align:center' class='tdRegistroSearch'><span class='insumo-stock-pill insumo-stock-pill--" + estadoStock.clase + "'>" + escaparHtmlAbmInsumos(estadoStock.texto) + "</span></td>";
		html += "<td id='td_datos_6' style='width:9%;text-align:center' class='tdRegistroSearch'><span class='insumo-estado-pill " + (esInactivo ? "insumo-estado-pill--inactivo" : "insumo-estado-pill--activo") + "'>" + escaparHtmlAbmInsumos(estado) + "</span></td>";
		html += "</tr></table>";
	}
	document.getElementById("table_abm_Insumos").innerHTML = html;
	actualizarResumenAbmInsumos(resumen);
}

function obtenerEstadoStockAbmInsumos(fila) {
	var stock = Number(fila.cant_stock || 0);
	var minimo = Number(fila.stock_minimo || 0);
	if (stock <= 0) {
		return { texto: "Sin stock", clase: "sin" };
	}
	if (minimo > 0 && stock < minimo) {
		return { texto: "Bajo minimo", clase: "bajo" };
	}
	return { texto: "OK", clase: "ok" };
}

function obtenerResumenVariantesAbmInsumos(fila) {
	if (String(fila.tiene_variantes || "0") != "1") {
		return "";
	}
	var variantes = fila.variantes || [];
	var nombres = [];
	for (var i = 0; i < variantes.length; i++) {
		if (String(variantes[i].estado || "Activo") != "Inactivo" && variantes[i].nombre_variante) {
			nombres.push(variantes[i].nombre_variante);
		}
	}
	var texto = nombres.length > 0 ? "Variantes: " + nombres.slice(0, 4).join(", ") + (nombres.length > 4 ? "..." : "") : "Con variantes";
	return "<div class='insumo-cell-sub'><span class='insumo-variant-pill'>Con variantes</span> " + escaparHtmlAbmInsumos(texto) + "</div>";
}

function actualizarResumenAbmInsumos(resumen) {
	if (document.getElementById("resumenInsumosActivos")) {
		document.getElementById("resumenInsumosActivos").textContent = resumen.activos;
	}
	if (document.getElementById("resumenInsumosInactivos")) {
		document.getElementById("resumenInsumosInactivos").textContent = resumen.inactivos;
	}
	if (document.getElementById("resumenInsumosVariantes")) {
		document.getElementById("resumenInsumosVariantes").textContent = resumen.variantes;
	}
	if (document.getElementById("resumenInsumosBajo")) {
		document.getElementById("resumenInsumosBajo").textContent = resumen.bajo;
	}
}

function inactivarAbmInsumosDesdeFila(idInsumo, event) {
	if (event) {
		event.stopPropagation();
	}
	var fila = document.querySelector('#table_abm_Insumos tr[data-id-insumo="' + String(idInsumo) + '"]');
	if (fila) {
		ObtenerdatosAbmInsumos(fila);
	}
	idAbmInsumos = String(idInsumo || "");
	eliminarAbmInsumos();
}

function eliminarAbmInsumos() {
	if (idAbmInsumos == "") {
		ver_vetana_informativa("FALTO SELECCIONAR UN REGISTRO");
		return;
	}
	if (!confirm("Deseas inactivar este insumo?\nNo se eliminara su historial de stock, movimientos ni tratamientos vinculados.")) {
		return;
	}
	verCerrarEfectoCargando("1");
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"id_insumo": idAbmInsumos,
		"funt": "EliminarInsumo"
	};
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		error: function (jqXHR, textstatus, errorThrowm) {
			verCerrarEfectoCargando("");
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
		},
		success: function (responseText) {
			verCerrarEfectoCargando("");
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) == true) {
					ver_vetana_informativa("REGISTRO ACTUALIZADO CORRECTAMENTE...");
					limpiarCamposAbmInsumos();
					buscarAbmInsumos();
				}
			} catch (error) {
				ver_vetana_informativa("LO SENTIMOS HA OCURRIDO UN ERROR");
				GuardarArchivosLog("Error: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function cargarProductosDisponiblesAbmInsumos(callback) {
	if (productosDisponiblesAbmInsumosCargados == true) {
		if (typeof callback == "function") {
			callback();
		}
		return;
	}
	if (typeof callback == "function") {
		callbacksProductosDisponiblesAbmInsumos.push(callback);
	}
	if (productosDisponiblesAbmInsumosCargando == true) {
		return;
	}
	productosDisponiblesAbmInsumosCargando = true;
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"funt": "obtener_productos_lista"
	};
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		error: function (jqXHR, textstatus, errorThrowm) {
			productosDisponiblesAbmInsumosCargando = false;
			callbacksProductosDisponiblesAbmInsumos = [];
			ver_vetana_informativa("NO SE PUDO CARGAR LA LISTA DE PRODUCTOS");
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
		},
		success: function (responseText) {
			productosDisponiblesAbmInsumosCargando = false;
			try {
				if (String(responseText || "").trim() == "") {
					throw new Error("Respuesta vacia de abmInsumos.php al cargar tratamientos");
				}
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) != true) {
					callbacksProductosDisponiblesAbmInsumos = [];
					ver_vetana_informativa(datos["mensaje"] || "NO SE PUDO CARGAR LA LISTA DE PRODUCTOS");
					return;
				}
				productosDisponiblesAbmInsumos = datos.productos_lista || [];
				productosDisponiblesAbmInsumosCargados = true;
				while (callbacksProductosDisponiblesAbmInsumos.length > 0) {
					callbacksProductosDisponiblesAbmInsumos.shift()();
				}
			} catch (error) {
				callbacksProductosDisponiblesAbmInsumos = [];
				ver_vetana_informativa("NO SE PUDO CARGAR LA LISTA DE PRODUCTOS");
				GuardarArchivosLog("Error cargarProductosDisponiblesAbmInsumos: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function cargarProductosAsociadosAbmInsumos(idInsumo) {
	productosSeleccionadosAbmInsumos = {};
	document.getElementById("divProductosInsumo").innerHTML = paginacargando;
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"id_insumo": idInsumo,
		"funt": "obtener_productos_asociados"
	};
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				var productos = datos.productos || [];
				for (var i = 0; i < productos.length; i++) {
					productosSeleccionadosAbmInsumos[String(productos[i].cod_producto)] = productos[i].cantidad || 1;
				}
				cargarProductosDisponiblesAbmInsumos(function () {
					renderProductosInsumoSeleccionables();
				});
			} catch (error) {}
		}
	});
}

function agregarFilaProductoInsumo(codProducto, cantidad) {
	if (codProducto) {
		productosSeleccionadosAbmInsumos[String(codProducto)] = cantidad || 1;
	}
	renderProductosInsumoSeleccionables();
}

function seleccionarTodosProductosInsumo() {
	if (productosDisponiblesAbmInsumosCargados == false) {
		cargarProductosDisponiblesAbmInsumos(function () {
			seleccionarTodosProductosInsumo();
		});
		return;
	}
	if (productosDisponiblesAbmInsumos.length == 0) {
		ver_vetana_informativa("No hay tratamientos disponibles para seleccionar.");
		return;
	}
	for (var i = 0; i < productosDisponiblesAbmInsumos.length; i++) {
		var cod = String(productosDisponiblesAbmInsumos[i].cod_producto || "");
		if (cod == "") {
			continue;
		}
		if (!productosSeleccionadosAbmInsumos.hasOwnProperty(cod)) {
			productosSeleccionadosAbmInsumos[cod] = 1;
		}
	}
	renderProductosInsumoSeleccionables();
}

function renderProductosInsumoSeleccionables(seleccionados) {
	if (seleccionados) {
		productosSeleccionadosAbmInsumos = seleccionados;
	}
	if (productosDisponiblesAbmInsumosCargados == false) {
		cargarProductosDisponiblesAbmInsumos(function () {
			renderProductosInsumoSeleccionables(seleccionados);
		});
		return;
	}
	var contenedor = document.getElementById("divProductosInsumo");
	if (!contenedor) {
		return;
	}
	if (productosDisponiblesAbmInsumos.length == 0) {
		contenedor.innerHTML = "<p class='pTituloC' style='padding:14px;text-align:center;color:#607080'>No hay tratamientos disponibles.</p>";
		return;
	}
	var filtro = document.getElementById("inptBuscarProductoInsumo") ? document.getElementById("inptBuscarProductoInsumo").value.toLowerCase() : "";
	var html = "";
	var visibles = 0;
	var productosOrdenados = productosDisponiblesAbmInsumos.slice().sort(function (a, b) {
		var aSeleccionado = productosSeleccionadosAbmInsumos.hasOwnProperty(String(a.cod_producto || "")) ? 0 : 1;
		var bSeleccionado = productosSeleccionadosAbmInsumos.hasOwnProperty(String(b.cod_producto || "")) ? 0 : 1;
		if (aSeleccionado !== bSeleccionado) {
			return aSeleccionado - bSeleccionado;
		}
		return String(a.nombre_producto || "").localeCompare(String(b.nombre_producto || ""));
	});
	for (var i = 0; i < productosOrdenados.length; i++) {
		var producto = productosOrdenados[i];
		var cod = String(producto.cod_producto || "");
		var nombreProducto = producto.nombre_producto || "";
		var etiquetaProducto = cod + " | " + nombreProducto;
		if (filtro != "" && etiquetaProducto.toLowerCase().indexOf(filtro) < 0) {
			continue;
		}
		visibles++;
		var checked = productosSeleccionadosAbmInsumos.hasOwnProperty(cod);
		var cantidad = checked ? productosSeleccionadosAbmInsumos[cod] : 1;
		html += "<label class='insumo-producto-card" + (checked ? " insumo-producto-card--activo" : "") + "'>";
		html += "<input type='checkbox' class='insumo-producto-check' value='" + escaparHtmlAbmInsumos(cod) + "' " + (checked ? "checked" : "") + " onchange='toggleProductoInsumoSeleccionado(this)'>";
		html += "<span class='insumo-producto-nombre' title='" + escaparHtmlAbmInsumos(etiquetaProducto) + "'>" + escaparHtmlAbmInsumos(etiquetaProducto) + "</span>";
		html += "<input type='number' class='inputText insumo-producto-cantidad' value='" + escaparHtmlAbmInsumos(cantidad) + "' min='0.01' step='any' " + (checked ? "" : "disabled") + " onclick='event.stopPropagation()' onchange='actualizarCantidadProductoInsumo(this)'>";
		html += "</label>";
	}
	if (visibles == 0) {
		html = "<p class='pTituloC' style='padding:14px;text-align:center;color:#607080'>No hay tratamientos que coincidan con la busqueda.</p>";
	}
	contenedor.innerHTML = html;
}

function toggleProductoInsumoSeleccionado(check) {
	var card = check.closest(".insumo-producto-card");
	var cantidad = card ? card.querySelector(".insumo-producto-cantidad") : null;
	if (check.checked) {
		productosSeleccionadosAbmInsumos[String(check.value)] = cantidad && cantidad.value ? cantidad.value : 1;
		if (cantidad) {
			cantidad.disabled = false;
			if (!cantidad.value) {
				cantidad.value = 1;
			}
		}
	} else {
		delete productosSeleccionadosAbmInsumos[String(check.value)];
		if (cantidad) {
			cantidad.disabled = true;
		}
	}
	if (card) {
		card.classList.toggle("insumo-producto-card--activo", check.checked);
	}
}

function actualizarCantidadProductoInsumo(input) {
	var card = input.closest(".insumo-producto-card");
	var check = card ? card.querySelector(".insumo-producto-check") : null;
	if (check && check.checked) {
		productosSeleccionadosAbmInsumos[String(check.value)] = input.value || 1;
	}
}

function escaparHtmlAbmInsumos(valor) {
	return String(valor == null ? "" : valor)
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&#039;");
}

function formatearCantidadReposicionInsumos(valor) {
	var numero = parseFloat(String(valor == null ? 0 : valor).replace(",", "."));
	if (isNaN(numero)) {
		return "0";
	}
	if (Math.abs(numero - Math.round(numero)) < 0.0001) {
		return String(Math.round(numero));
	}
	return numero.toFixed(3).replace(/0+$/, "").replace(/\.$/, "");
}

var dashboardInsumosLocales = [];
var dashboardInsumosConsultorios = [];
var dashboardInsumosInsumos = [];
var dashboardInsumosCatalogosCargados = false;
var reposicionInsumosSeleccionados = {};
var reposicionInsumosPorConsultorio = {};

function verCerrarDashboardInsumos() {
	if (document.getElementById("divAbmInsumos") && document.getElementById("divAbmInsumos").style.display != "") {
		verCerrarAbmInsumos();
	}
	verTabInsumos("stock");
}

function minimizarDashboardInsumos() {
	minimizarAbmInsumos();
}

function cargarCatalogosDashboardInsumos(callback) {
	if (dashboardInsumosCatalogosCargados == true) {
		if (typeof callback == "function") {
			callback();
		}
		return;
	}
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"funt": "dashboard_catalogos"
	};
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		error: function (jqXHR, textstatus, errorThrowm) {
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
		},
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) == true) {
					dashboardInsumosLocales = datos.locales || [];
					dashboardInsumosConsultorios = datos.consultorios || [];
					dashboardInsumosInsumos = datos.insumos || [];
					dashboardInsumosCatalogosCargados = true;
					renderCatalogosDashboardInsumos();
					if (typeof callback == "function") {
						callback();
					}
				} else {
					ver_vetana_informativa(datos.mensaje || "No se pudieron cargar los catalogos del dashboard.");
				}
			} catch (error) {
				ver_vetana_informativa("LO SENTIMOS HA OCURRIDO UN ERROR");
				GuardarArchivosLog("Error: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function renderCatalogosDashboardInsumos() {
	var opcionesLocales = "<option value=''>Todas las sucursales</option>";
	for (var i = 0; i < dashboardInsumosLocales.length; i++) {
		opcionesLocales += "<option value='" + escaparHtmlAbmInsumos(dashboardInsumosLocales[i].cod_local) + "'>" + escaparHtmlAbmInsumos(dashboardInsumosLocales[i].Nombre) + "</option>";
	}
	document.getElementById("inptDashboardInsumosLocal").innerHTML = opcionesLocales;

	if (document.getElementById("inptDashboardInsumosInsumo")) {
		document.getElementById("inptDashboardInsumosInsumo").innerHTML = opcionesInsumosInsumos("Seleccionar insumo");
	}
	renderFiltroDescripcionDashboardInsumos();
	filtrarConsultoriosDashboardInsumos();
}

function renderFiltroDescripcionDashboardInsumos() {
	if (!document.getElementById("filtroDashboardInsumosDescripcion")) {
		return;
	}
	var opciones = "<option value=''>Todas las descripciones</option>";
	var selectDescripcionAbm = document.getElementById("inptDescripcionInsumo");
	if (!selectDescripcionAbm) {
		document.getElementById("filtroDashboardInsumosDescripcion").innerHTML = opciones;
		return;
	}
	for (var i = 0; i < selectDescripcionAbm.options.length; i++) {
		var option = selectDescripcionAbm.options[i];
		var valor = String(option.value || "").trim();
		if (valor == "") {
			continue;
		}
		opciones += "<option value='" + escaparHtmlAbmInsumos(valor) + "'>" + escaparHtmlAbmInsumos(option.text || valor) + "</option>";
	}
	document.getElementById("filtroDashboardInsumosDescripcion").innerHTML = opciones;
}

function parseValorInsumoVariante(valor) {
	var partes = String(valor || "").split(":");
	return { id_insumo: partes[0] || "", id_variante: partes.length > 1 ? partes[1] : "0" };
}

function filtrarConsultoriosDashboardInsumos() {
	var codLocal = document.getElementById("inptDashboardInsumosLocal").value;
	var opciones = "<option value=''>Todos los consultorios</option>";
	for (var i = 0; i < dashboardInsumosConsultorios.length; i++) {
		var consultorio = dashboardInsumosConsultorios[i];
		if (codLocal != "" && String(consultorio.cod_localFk) != String(codLocal)) {
			continue;
		}
		opciones += "<option value='" + escaparHtmlAbmInsumos(consultorio.id_consultorio) + "'>" + escaparHtmlAbmInsumos(consultorio.nombre) + "</option>";
	}
	document.getElementById("inptDashboardInsumosConsultorio").innerHTML = opciones;
}

function limpiarFiltrosDashboardInsumos() {
	document.getElementById("inptDashboardInsumosLocal").value = "";
	filtrarConsultoriosDashboardInsumos();
	document.getElementById("inptDashboardInsumosConsultorio").value = "";
	document.getElementById("inptDashboardInsumosBuscar").value = "";
	if (document.getElementById("filtroDashboardInsumosDescripcion")) {
		document.getElementById("filtroDashboardInsumosDescripcion").value = "";
	}
	if (document.getElementById("inptDashboardInsumosInsumo")) {
		document.getElementById("inptDashboardInsumosInsumo").value = "";
	}
	if (document.getElementById("inptDashboardInsumosCantidad")) {
		document.getElementById("inptDashboardInsumosCantidad").value = "";
	}
	buscarDashboardInsumosStock();
}

function buscarDashboardInsumosStock() {
	if (!document.getElementById("tableDashboardInsumosStock")) {
		return;
	}
	document.getElementById("tableDashboardInsumosStock").innerHTML = paginacargando;
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"cod_local": document.getElementById("inptDashboardInsumosLocal").value,
		"id_consultorio": document.getElementById("inptDashboardInsumosConsultorio").value,
		"buscar": document.getElementById("inptDashboardInsumosBuscar").value,
		"descripcion": document.getElementById("filtroDashboardInsumosDescripcion") ? document.getElementById("filtroDashboardInsumosDescripcion").value : "",
		"funt": "dashboard_listar_stock"
	};
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		error: function (jqXHR, textstatus, errorThrowm) {
			document.getElementById("tableDashboardInsumosStock").innerHTML = "";
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
		},
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) == true) {
					renderTablaDashboardInsumosStock(datos.filas || []);
				} else {
					document.getElementById("tableDashboardInsumosStock").innerHTML = "";
					ver_vetana_informativa(datos.mensaje || "No se pudo listar el stock.");
				}
			} catch (error) {
				document.getElementById("tableDashboardInsumosStock").innerHTML = "";
				ver_vetana_informativa("LO SENTIMOS HA OCURRIDO UN ERROR");
				GuardarArchivosLog("Error: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function renderTablaDashboardInsumosStock(filas) {
	var html = "";
	var totalStock = 0;
	for (var i = 0; i < filas.length; i++) {
		var fila = filas[i];
		var cantidad = Number(fila.cantidad || 0);
		var stockMinimo = Number(fila.stock_minimo || 0);
		var diferencia = cantidad - stockMinimo;
		var estadoStock = cantidad <= 0 ? { texto: "Sin stock", clase: "sin" } : (stockMinimo > 0 && cantidad < stockMinimo ? { texto: "Bajo", clase: "bajo" } : { texto: "OK", clase: "ok" });
		var claseBajo = stockMinimo > 0 && cantidad < stockMinimo ? " insumo-stock-bajo" : "";
		var claveFila = obtenerClaveFilaDashboardInsumosStock(fila.cod_local, fila.id_consultorio, fila.id_insumo, fila.id_variante || 0);
		totalStock += cantidad;
		html += "<table class='tableRegistroSearch' border='1' cellspacing='1' cellpadding='5' style='width:100%'>";
		html += "<tr class='" + claseBajo + "' data-stock-key='" + escaparHtmlAbmInsumos(claveFila) + "' onclick='seleccionarFilaDashboardInsumos(this)'>";
		html += "<td id='td_local' style='display:none'>" + escaparHtmlAbmInsumos(fila.cod_local) + "</td>";
		html += "<td id='td_consultorio' style='display:none'>" + escaparHtmlAbmInsumos(fila.id_consultorio) + "</td>";
		html += "<td id='td_insumo' style='display:none'>" + escaparHtmlAbmInsumos(fila.id_insumo) + "</td>";
		html += "<td id='td_variante' style='display:none'>" + escaparHtmlAbmInsumos(fila.id_variante || 0) + "</td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-local'>" + escaparHtmlAbmInsumos(fila.nombre_local) + "</td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-consultorio'>" + escaparHtmlAbmInsumos(fila.nombre_consultorio) + "</td>";
		var nombreConVariante = fila.nombre + (fila.nombre_variante ? " - " + fila.nombre_variante : "");
		html += "<td class='tdRegistroSearch dashboard-stock-col-insumo dashboard-stock-col-insumo-cell'>" + escaparHtmlAbmInsumos(nombreConVariante) + "</td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-descripcion'>" + escaparHtmlAbmInsumos(fila.descripcion || "") + "</td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-stock'><input class='dashboard-insumos-stock-input' type='number' min='0' step='any' value='" + escaparHtmlAbmInsumos(fila.cantidad || 0) + "' onclick='event.stopPropagation()'></td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-unidad'>" + escaparHtmlAbmInsumos(fila.unidad_medida) + "</td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-minimo'>" + escaparHtmlAbmInsumos(fila.stock_minimo || 0) + "</td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-dif'>" + escaparHtmlAbmInsumos(diferencia.toFixed(2).replace(/\.00$/, "")) + "</td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-estado'><span class='insumo-stock-pill insumo-stock-pill--" + estadoStock.clase + "'>" + escaparHtmlAbmInsumos(estadoStock.texto) + "</span></td>";
		html += "<td class='tdRegistroSearch dashboard-stock-col-accion'><input type='button' class='btn4' value='OK' style='width:48px;height:28px;padding:0;border-radius:7px' onclick='guardarDashboardInsumosStockDesdeFila(this);event.stopPropagation();'></td>";
		html += "</tr></table>";
	}
	if (html == "") {
		html = "<p class='pTituloC' style='padding:16px;text-align:center;color:#607080'>No hay stock cargado para los filtros seleccionados.</p>";
	}
	document.getElementById("tableDashboardInsumosStock").innerHTML = html;
	document.getElementById("lblDashboardInsumosResumen").textContent = "Registros: " + filas.length + " | Stock total: " + totalStock.toFixed(2);
	restaurarVistaDashboardInsumosStock();
}

function obtenerClaveFilaDashboardInsumosStock(codLocal, idConsultorio, idInsumo, idVariante) {
	return [codLocal || "", idConsultorio || "", idInsumo || "", idVariante || "0"].join("|");
}

function restaurarVistaDashboardInsumosStock() {
	if (!dashboardInsumosStockFilaPendiente) {
		return;
	}
	var contenedor = document.getElementById("tableDashboardInsumosStock");
	if (!contenedor) {
		dashboardInsumosStockFilaPendiente = null;
		return;
	}
	var selector = 'tr[data-stock-key="' + String(dashboardInsumosStockFilaPendiente).replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"]';
	var fila = contenedor.querySelector(selector);
	dashboardInsumosStockFilaPendiente = null;
	if (!fila) {
		return;
	}
	seleccionarFilaDashboardInsumos(fila);
	setTimeout(function () {
		fila.scrollIntoView({ block: "center", inline: "nearest" });
		var inputStock = fila.querySelector(".dashboard-insumos-stock-input");
		if (inputStock) {
			inputStock.focus();
			inputStock.select();
		}
	}, 0);
}

function seleccionarFilaDashboardInsumos(fila) {
	document.getElementById("inptDashboardInsumosLocal").value = $(fila).children("#td_local").html();
	filtrarConsultoriosDashboardInsumos();
	document.getElementById("inptDashboardInsumosConsultorio").value = $(fila).children("#td_consultorio").html();
	if (document.getElementById("inptDashboardInsumosInsumo")) {
		document.getElementById("inptDashboardInsumosInsumo").value = $(fila).children("#td_insumo").html() + ":" + ($(fila).children("#td_variante").html() || "0");
	}
	if (document.getElementById("inptDashboardInsumosCantidad")) {
		document.getElementById("inptDashboardInsumosCantidad").value = $(fila).find(".dashboard-insumos-stock-input").val();
	}
}

function guardarDashboardInsumosStock() {
	if (!document.getElementById("inptDashboardInsumosInsumo") || !document.getElementById("inptDashboardInsumosCantidad")) {
		return;
	}
	var codLocal = document.getElementById("inptDashboardInsumosLocal").value;
	var idConsultorio = document.getElementById("inptDashboardInsumosConsultorio").value;
	var seleccion = parseValorInsumoVariante(document.getElementById("inptDashboardInsumosInsumo").value);
	var cantidad = document.getElementById("inptDashboardInsumosCantidad").value;
	guardarDashboardInsumosStockDatos(seleccion.id_insumo, codLocal, idConsultorio, cantidad, seleccion.id_variante);
}

function guardarDashboardInsumosStockDesdeFila(boton) {
	var fila = boton.closest("tr");
	guardarDashboardInsumosStockDatos(
		$(fila).children("#td_insumo").html(),
		$(fila).children("#td_local").html(),
		$(fila).children("#td_consultorio").html(),
		$(fila).find(".dashboard-insumos-stock-input").val(),
		$(fila).children("#td_variante").html() || "0"
	);
}

function guardarDashboardInsumosStockDatos(idInsumo, codLocal, idConsultorio, cantidad, idVariante) {
	if (codLocal == "" || idConsultorio == "" || idInsumo == "" || cantidad === "") {
		ver_vetana_informativa("Faltan datos", "Seleccione sucursal, consultorio, insumo y cantidad.", "error");
		return;
	}
	dashboardInsumosStockFilaPendiente = obtenerClaveFilaDashboardInsumosStock(codLocal, idConsultorio, idInsumo, idVariante || "0");
	verCerrarEfectoCargando("1");
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"id_insumo": idInsumo,
		"id_variante": idVariante || "0",
		"cod_local": codLocal,
		"id_consultorio": idConsultorio,
		"cantidad": cantidad,
		"funt": "dashboard_guardar_stock"
	};
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		error: function (jqXHR, textstatus, errorThrowm) {
			verCerrarEfectoCargando("");
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
		},
		success: function (responseText) {
			verCerrarEfectoCargando("");
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) == true) {
					ver_vetana_informativa(datos.mensaje || "Stock actualizado correctamente.");
					buscarDashboardInsumosStock();
				} else {
					ver_vetana_informativa(datos.mensaje || "No se pudo guardar el stock.", "", "error");
				}
			} catch (error) {
				ver_vetana_informativa("LO SENTIMOS HA OCURRIDO UN ERROR");
				GuardarArchivosLog("Error: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function opcionesLocalesInsumos(textoInicial) {
	var html = "<option value=''>" + (textoInicial || "Seleccionar") + "</option>";
	for (var i = 0; i < dashboardInsumosLocales.length; i++) {
		html += "<option value='" + escaparHtmlAbmInsumos(dashboardInsumosLocales[i].cod_local) + "'>" + escaparHtmlAbmInsumos(dashboardInsumosLocales[i].Nombre) + "</option>";
	}
	return html;
}

function opcionesInsumosInsumos(textoInicial, filtro) {
	var html = "<option value=''>" + (textoInicial || "Seleccionar") + "</option>";
	var textoFiltro = String(filtro || "").toLowerCase().trim();
	for (var i = 0; i < dashboardInsumosInsumos.length; i++) {
		var insumo = dashboardInsumosInsumos[i];
		var id = String(insumo.id_insumo || "");
		var nombre = String(insumo.nombre || "");
		var unidad = String(insumo.unidad_medida || "");
		if (String(insumo.tiene_variantes || "0") == "1") {
			var variantes = insumo.variantes || [];
			for (var j = 0; j < variantes.length; j++) {
				if (variantes[j].estado == "Inactivo") {
					continue;
				}
				var etiquetaVariante = id + " | " + nombre + " - " + (variantes[j].nombre_variante || "") + (unidad != "" ? " (" + unidad + ")" : "");
				if (textoFiltro != "" && etiquetaVariante.toLowerCase().indexOf(textoFiltro) < 0) {
					continue;
				}
				html += "<option value='" + escaparHtmlAbmInsumos(id + ":" + (variantes[j].id_variante || 0)) + "'>" + escaparHtmlAbmInsumos(etiquetaVariante) + "</option>";
			}
		} else {
			var etiqueta = id + " | " + nombre + (unidad != "" ? " (" + unidad + ")" : "");
			if (textoFiltro != "" && etiqueta.toLowerCase().indexOf(textoFiltro) < 0) {
				continue;
			}
			html += "<option value='" + escaparHtmlAbmInsumos(id + ":0") + "'>" + escaparHtmlAbmInsumos(etiqueta) + "</option>";
		}
	}
	return html;
}

function prepararReposicionInsumos() {
	var locales = ["inptMovimientoInsumoLocal"];
	for (var i = 0; i < locales.length; i++) {
		if (document.getElementById(locales[i])) {
			document.getElementById(locales[i]).innerHTML = opcionesLocalesInsumos(locales[i].indexOf("filtro") === 0 ? "Todos" : "Seleccionar");
		}
	}
	var hoy = new Date().toISOString().slice(0, 10);
	if (document.getElementById("inptMovimientoInsumoFecha") && document.getElementById("inptMovimientoInsumoFecha").value == "") {
		document.getElementById("inptMovimientoInsumoFecha").value = hoy;
	}
	filtrarConsultoriosGenericoInsumos("inptMovimientoInsumoLocal", "inptMovimientoInsumoConsultorio");
	reposicionInsumosSeleccionados = {};
	reposicionInsumosPorConsultorio = {};
	renderListaReposicionInsumos();
	actualizarContadorReposicionInsumos();
	renderResumenConsultoriosReposicionInsumos();
	limpiarHiloReposicionInsumos();
}

function filtrarConsultoriosGenericoInsumos(idLocal, idConsultorio) {
	if (!document.getElementById(idLocal) || !document.getElementById(idConsultorio)) {
		return;
	}
	var codLocal = document.getElementById(idLocal).value;
	var html = "<option value=''>Seleccionar</option>";
	for (var i = 0; i < dashboardInsumosConsultorios.length; i++) {
		var consultorio = dashboardInsumosConsultorios[i];
		if (codLocal != "" && String(consultorio.cod_localFk) != String(codLocal)) {
			continue;
		}
		html += "<option value='" + escaparHtmlAbmInsumos(consultorio.id_consultorio) + "'>" + escaparHtmlAbmInsumos(consultorio.nombre) + "</option>";
	}
	document.getElementById(idConsultorio).innerHTML = html;
}

function cambiarSucursalReposicionInsumos() {
	reposicionInsumosSeleccionados = {};
	reposicionInsumosPorConsultorio = {};
	filtrarConsultoriosGenericoInsumos("inptMovimientoInsumoLocal", "inptMovimientoInsumoConsultorio");
	renderListaReposicionInsumos();
	renderResumenConsultoriosReposicionInsumos();
	limpiarHiloReposicionInsumos();
}

function limpiarHiloReposicionInsumos() {
	var input = document.getElementById("inptReposicionBuscarHilo");
	var id = document.getElementById("inptReposicionHiloId");
	var lista = document.getElementById("listaHilosReposicionInsumos");
	var etiqueta = document.getElementById("lblReposicionHiloSeleccionado");
	if (input) { input.value = ""; }
	if (id) { id.value = ""; }
	if (lista) {
		lista.innerHTML = "";
		lista.style.display = "none";
	}
	if (etiqueta) {
		etiqueta.innerHTML = "Seleccione obligatoriamente el Hilo que recibir&aacute; el borrador.";
		etiqueta.classList.remove("seleccionado");
	}
}

function programarBusquedaHilosReposicionInsumos(texto) {
	var id = document.getElementById("inptReposicionHiloId");
	var etiqueta = document.getElementById("lblReposicionHiloSeleccionado");
	if (id) { id.value = ""; }
	if (etiqueta) {
		etiqueta.innerHTML = "Seleccione un resultado para vincular el borrador.";
		etiqueta.classList.remove("seleccionado");
	}
	if (temporizadorBusquedaHilosReposicionInsumos) {
		clearTimeout(temporizadorBusquedaHilosReposicionInsumos);
	}
	temporizadorBusquedaHilosReposicionInsumos = setTimeout(function () {
		buscarHilosReposicionInsumos(texto, true);
	}, 250);
}

function buscarHilosReposicionInsumos(texto, mostrarLista) {
	var local = document.getElementById("inptMovimientoInsumoLocal");
	var lista = document.getElementById("listaHilosReposicionInsumos");
	if (!local || local.value == "" || !lista) {
		if (lista) {
			lista.innerHTML = "<div class='insumos-reposicion-hilo-vacio'>Seleccione primero la sucursal destino.</div>";
			lista.style.display = mostrarLista ? "" : "none";
		}
		return;
	}
	var numeroSolicitud = ++solicitudBusquedaHilosReposicionInsumos;
	lista.innerHTML = "<div class='insumos-reposicion-hilo-vacio'>Buscando Hilos...</div>";
	lista.style.display = mostrarLista ? "" : "none";
	obtener_datos_user();
	$.ajax({
		data: {
			"useru": userid,
			"passu": passuser,
			"navegador": navegador,
			"cod_local": local.value,
			"buscar": texto || "",
			"funt": "buscar_hilos_reposicion"
		},
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		success: function (responseText) {
			if (numeroSolicitud != solicitudBusquedaHilosReposicionInsumos) {
				return;
			}
			try {
				var respuesta = $.parseJSON(responseText);
				var filas = respuesta.filas || [];
				var html = "";
				for (var i = 0; i < filas.length; i++) {
					html += "<button type='button' data-hilo-id='" + escaparHtmlAbmInsumos(filas[i].cod_interConsulta) + "' data-hilo-asunto='" + escaparHtmlAbmInsumos(filas[i].asunto || "") + "'>";
					html += "<b>" + escaparHtmlAbmInsumos(filas[i].asunto || "Hilo sin asunto") + "</b><span>Hilo #" + escaparHtmlAbmInsumos(filas[i].cod_interConsulta) + "</span></button>";
				}
				lista.innerHTML = html || "<div class='insumos-reposicion-hilo-vacio'>No se encontraron Hilos activos en esta sucursal.</div>";
				var botones = lista.querySelectorAll("button[data-hilo-id]");
				for (var b = 0; b < botones.length; b++) {
					botones[b].onclick = function () {
						seleccionarHiloReposicionInsumos(this.getAttribute("data-hilo-id"), this.getAttribute("data-hilo-asunto"));
					};
				}
				lista.style.display = mostrarLista ? "" : "none";
			} catch (error) {
				lista.innerHTML = "<div class='insumos-reposicion-hilo-vacio'>No se pudo cargar la lista de Hilos.</div>";
			}
		}
	});
}

function seleccionarHiloReposicionInsumos(codigo, asunto) {
	var input = document.getElementById("inptReposicionBuscarHilo");
	var id = document.getElementById("inptReposicionHiloId");
	var lista = document.getElementById("listaHilosReposicionInsumos");
	var etiqueta = document.getElementById("lblReposicionHiloSeleccionado");
	if (input) { input.value = asunto; }
	if (id) { id.value = codigo; }
	if (lista) { lista.style.display = "none"; }
	if (etiqueta) {
		etiqueta.innerHTML = "Vinculado con <b>" + escaparHtmlAbmInsumos(asunto) + "</b> &middot; Hilo #" + escaparHtmlAbmInsumos(codigo);
		etiqueta.classList.add("seleccionado");
	}
}

function cambiarConsultorioReposicionInsumos() {
	var select = document.getElementById("inptMovimientoInsumoConsultorio");
	var idConsultorio = select ? String(select.value || "") : "";
	if (idConsultorio == "") {
		reposicionInsumosSeleccionados = {};
	} else {
		if (!reposicionInsumosPorConsultorio[idConsultorio]) {
			reposicionInsumosPorConsultorio[idConsultorio] = {
				id_consultorio: idConsultorio,
				nombre: select.options[select.selectedIndex] ? select.options[select.selectedIndex].text : "Consultorio",
				items: {}
			};
		}
		reposicionInsumosSeleccionados = reposicionInsumosPorConsultorio[idConsultorio].items;
	}
	renderListaReposicionInsumos();
	renderResumenConsultoriosReposicionInsumos();
}

function seleccionarConsultorioCargadoReposicion(idConsultorio) {
	var select = document.getElementById("inptMovimientoInsumoConsultorio");
	if (!select || !select.querySelector("option[value='" + String(idConsultorio).replace(/'/g, "\\'") + "']")) {
		return;
	}
	select.value = String(idConsultorio);
	cambiarConsultorioReposicionInsumos();
}

function renderResumenConsultoriosReposicionInsumos() {
	var contenedor = document.getElementById("resumenConsultoriosReposicionInsumos");
	if (!contenedor) {
		return;
	}
	var ids = Object.keys(reposicionInsumosPorConsultorio);
	var activo = document.getElementById("inptMovimientoInsumoConsultorio") ? String(document.getElementById("inptMovimientoInsumoConsultorio").value || "") : "";
	var html = "";
	for (var i = 0; i < ids.length; i++) {
		var grupo = reposicionInsumosPorConsultorio[ids[i]];
		var total = Object.keys(grupo.items || {}).length;
		if (total == 0) {
			continue;
		}
		html += "<button type='button' class='insumos-reposicion-consultorio-chip" + (String(ids[i]) == activo ? " activo" : "") + "' onclick='seleccionarConsultorioCargadoReposicion(\"" + escaparHtmlAbmInsumos(ids[i]) + "\")'>";
		html += escaparHtmlAbmInsumos(grupo.nombre) + " <b>" + total + "</b></button>";
	}
	contenedor.innerHTML = html || "<span>Seleccione un consultorio y cargue sus insumos. Puede cambiar de consultorio sin perder lo ya cargado.</span>";
}

function obtenerFilasDisponiblesReposicionInsumos() {
	var filas = [];
	for (var i = 0; i < dashboardInsumosInsumos.length; i++) {
		var insumo = dashboardInsumosInsumos[i];
		var variantes = insumo.variantes || [];
		if (String(insumo.tiene_variantes || "0") == "1") {
			for (var v = 0; v < variantes.length; v++) {
				if (String(variantes[v].estado || "").toLowerCase() == "inactivo") {
					continue;
				}
				filas.push({
					clave: String(insumo.id_insumo) + ":" + String(variantes[v].id_variante || 0),
					id_insumo: insumo.id_insumo,
					id_variante: variantes[v].id_variante || 0,
					nombre: insumo.nombre || "",
					nombre_variante: variantes[v].nombre_variante || "",
					descripcion: insumo.descripcion || "",
					unidad_medida: insumo.unidad_medida || ""
				});
			}
		} else {
			filas.push({
				clave: String(insumo.id_insumo) + ":0",
				id_insumo: insumo.id_insumo,
				id_variante: 0,
				nombre: insumo.nombre || "",
				nombre_variante: "",
				descripcion: insumo.descripcion || "",
				unidad_medida: insumo.unidad_medida || ""
			});
		}
	}
	return filas;
}

function renderListaReposicionInsumos() {
	var contenedor = document.getElementById("listaReposicionInsumos");
	if (!contenedor) {
		return;
	}
	var idConsultorioActivo = document.getElementById("inptMovimientoInsumoConsultorio") ? document.getElementById("inptMovimientoInsumoConsultorio").value : "";
	if (idConsultorioActivo == "") {
		contenedor.innerHTML = "<div class='insumos-reposicion-vacio'>Seleccione el consultorio que desea cargar.</div>";
		actualizarContadorReposicionInsumos();
		return;
	}
	var buscar = document.getElementById("inptReposicionBuscarInsumo") ? document.getElementById("inptReposicionBuscarInsumo").value.toLowerCase().trim() : "";
	var mostrar = document.getElementById("inptReposicionFiltroLista") ? document.getElementById("inptReposicionFiltroLista").value : "todos";
	var filas = obtenerFilasDisponiblesReposicionInsumos();
	var html = "";
	for (var i = 0; i < filas.length; i++) {
		var fila = filas[i];
		var seleccionado = !!reposicionInsumosSeleccionados[fila.clave];
		var texto = [fila.id_insumo, fila.nombre, fila.nombre_variante, fila.descripcion, fila.unidad_medida].join(" ").toLowerCase();
		if ((buscar != "" && texto.indexOf(buscar) < 0) || (mostrar == "seleccionados" && !seleccionado)) {
			continue;
		}
		var cantidad = seleccionado ? reposicionInsumosSeleccionados[fila.clave].cantidad : "";
		var nombreCompleto = fila.nombre + (fila.nombre_variante ? " - " + fila.nombre_variante : "");
		html += "<div class='insumos-reposicion-item" + (seleccionado ? " seleccionado" : "") + "'>";
		html += "<label class='insumos-reposicion-check'><input type='checkbox' " + (seleccionado ? "checked" : "") + " onchange='seleccionarInsumoReposicion(\"" + fila.clave + "\",this.checked)'><span></span></label>";
		html += "<div class='insumos-reposicion-info'><b>" + escaparHtmlAbmInsumos(nombreCompleto) + "</b>";
		html += "<small>C&oacute;digo " + escaparHtmlAbmInsumos(fila.id_insumo) + (fila.descripcion ? " &middot; " + escaparHtmlAbmInsumos(fila.descripcion) : "") + "</small></div>";
		html += "<span class='insumos-reposicion-unidad'>" + escaparHtmlAbmInsumos(fila.unidad_medida) + "</span>";
		html += "<input class='inputText insumos-reposicion-cantidad' type='number' min='0.001' step='any' placeholder='Cantidad' value='" + escaparHtmlAbmInsumos(cantidad) + "' " + (seleccionado ? "" : "disabled") + " oninput='actualizarCantidadReposicionInsumo(\"" + fila.clave + "\",this.value)'>";
		html += "</div>";
	}
	contenedor.innerHTML = html || "<div class='insumos-reposicion-vacio'>No hay insumos que coincidan con los filtros.</div>";
	actualizarContadorReposicionInsumos();
}

function seleccionarInsumoReposicion(clave, seleccionado) {
	var filas = obtenerFilasDisponiblesReposicionInsumos();
	if (seleccionado) {
		for (var i = 0; i < filas.length; i++) {
			if (filas[i].clave == clave) {
				reposicionInsumosSeleccionados[clave] = {
					id_insumo: filas[i].id_insumo,
					id_variante: filas[i].id_variante,
					nombre: filas[i].nombre,
					nombre_variante: filas[i].nombre_variante,
					unidad_medida: filas[i].unidad_medida,
					cantidad: ""
				};
				break;
			}
		}
	} else {
		delete reposicionInsumosSeleccionados[clave];
	}
	renderListaReposicionInsumos();
	renderResumenConsultoriosReposicionInsumos();
}

function actualizarCantidadReposicionInsumo(clave, cantidad) {
	if (reposicionInsumosSeleccionados[clave]) {
		reposicionInsumosSeleccionados[clave].cantidad = cantidad;
	}
}

function actualizarContadorReposicionInsumos() {
	var total = Object.keys(reposicionInsumosSeleccionados).length;
	var etiqueta = document.getElementById("lblReposicionInsumosSeleccionados");
	if (etiqueta) {
		var select = document.getElementById("inptMovimientoInsumoConsultorio");
		var nombre = select && select.selectedIndex >= 0 ? select.options[select.selectedIndex].text : "";
		etiqueta.innerHTML = total + (total == 1 ? " seleccionado" : " seleccionados") + (nombre && select.value ? " en " + escaparHtmlAbmInsumos(nombre) : "");
	}
}

function limpiarReposicionInsumos() {
	var select = document.getElementById("inptMovimientoInsumoConsultorio");
	var idConsultorio = select ? String(select.value || "") : "";
	if (idConsultorio != "") {
		reposicionInsumosPorConsultorio[idConsultorio] = {
			id_consultorio: idConsultorio,
			nombre: select.options[select.selectedIndex] ? select.options[select.selectedIndex].text : "Consultorio",
			items: {}
		};
		reposicionInsumosSeleccionados = reposicionInsumosPorConsultorio[idConsultorio].items;
	} else {
		reposicionInsumosSeleccionados = {};
	}
	renderListaReposicionInsumos();
	renderResumenConsultoriosReposicionInsumos();
}

function guardarReposicionInsumos() {
	var local = document.getElementById("inptMovimientoInsumoLocal").value;
	var codInterConsulta = document.getElementById("inptReposicionHiloId").value;
	var fecha = document.getElementById("inptMovimientoInsumoFecha").value;
	var motivo = document.getElementById("inptMovimientoInsumoMotivo").value.trim();
	var detallesReposicion = [];
	var idsConsultorios = Object.keys(reposicionInsumosPorConsultorio);
	for (var g = 0; g < idsConsultorios.length; g++) {
		var grupo = reposicionInsumosPorConsultorio[idsConsultorios[g]];
		var clavesGrupo = Object.keys(grupo.items || {});
		for (var d = 0; d < clavesGrupo.length; d++) {
			detallesReposicion.push({
				id_consultorio: grupo.id_consultorio,
				detalle: grupo.items[clavesGrupo[d]]
			});
		}
	}
	if (local == "" || codInterConsulta == "" || fecha == "" || motivo == "") {
		ver_vetana_informativa("Complete la sucursal, seleccione un Hilo, la fecha y el motivo.", "", "error");
		return;
	}
	if (detallesReposicion.length == 0) {
		ver_vetana_informativa("Cargue al menos un insumo para uno de los consultorios.", "", "error");
		return;
	}
	for (var c = 0; c < detallesReposicion.length; c++) {
		if (Number(detallesReposicion[c].detalle.cantidad) <= 0) {
			ver_vetana_informativa("Ingrese una cantidad valida para todos los insumos de cada consultorio.", "", "error");
			return;
		}
	}
	obtener_datos_user();
	var datos = new FormData();
	datos.append("useru", userid);
	datos.append("passu", passuser);
	datos.append("navegador", navegador);
	datos.append("cod_local", local);
	datos.append("cod_interConsulta", codInterConsulta);
	datos.append("motivo", motivo);
	datos.append("fecha", fecha);
	datos.append("funt", "guardar_reposicion");
	for (var i = 0; i < detallesReposicion.length; i++) {
		var detalle = detallesReposicion[i].detalle;
		datos.append("id_consultorio[]", detallesReposicion[i].id_consultorio);
		datos.append("id_insumo[]", detalle.id_insumo);
		datos.append("id_variante[]", detalle.id_variante || "0");
		datos.append("cantidad[]", detalle.cantidad);
	}
	var boton = document.getElementById("btnGuardarReposicionInsumos");
	if (boton) { boton.disabled = true; }
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		cache: false,
		contentType: false,
		processData: false,
		complete: function () {
			if (boton) { boton.disabled = false; }
		},
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) == true) {
					ver_vetana_informativa(datos.mensaje || "Reposicion guardada.");
					codigoReposicionInsumoSeleccionada = datos.codigo || "";
					actualizarEstadoBotonPdfMovimientoInsumos();
					document.getElementById("inptMovimientoInsumoMotivo").value = "";
					limpiarHiloReposicionInsumos();
					reposicionInsumosSeleccionados = {};
					reposicionInsumosPorConsultorio = {};
					cambiarConsultorioReposicionInsumos();
					toggleHistorialMovimientosInsumos(true);
					listarReposicionesInsumos();
				} else {
					ver_vetana_informativa(datos.mensaje || "No se pudo guardar la reposicion.", "", "error");
				}
			} catch (error) {
				GuardarArchivosLog("Error: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function listarReposicionesInsumos() {
	obtener_datos_user();
	var datos = {
		"useru": userid,
		"passu": passuser,
		"navegador": navegador,
		"fecha_desde": document.getElementById("filtroMovimientoDesde").value,
		"fecha_hasta": document.getElementById("filtroMovimientoHasta").value,
		"estado": document.getElementById("filtroReposicionEstado").value,
		"funt": "listar_reposiciones"
	};
	document.getElementById("tableMovimientosInsumos").innerHTML = paginacargando;
	$.ajax({
		data: datos,
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				var filas = datos.filas || [];
				var html = "";
				for (var i = 0; i < filas.length; i++) {
					var f = filas[i];
					var pendiente = String(f.estado).toLowerCase() == "pendiente";
					html += "<table class='tableRegistroSearch' border='1' cellspacing='1' cellpadding='5' style='width:100%'><tr onclick='verDetalleReposicionInsumos(\"" + escaparHtmlAbmInsumos(f.codigo) + "\")'>";
					html += "<td class='tdRegistroSearch' style='width:16%'>" + escaparHtmlAbmInsumos(f.fecha_envio) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:12%'><span class='reposicion-estado reposicion-estado-" + escaparHtmlAbmInsumos(f.estado) + "'>" + escaparHtmlAbmInsumos(f.estado) + "</span></td>";
					html += "<td class='tdRegistroSearch' style='width:18%'>" + escaparHtmlAbmInsumos(f.nombre_local) + (f.asunto_hilo ? "<small class='insumos-reposicion-hilo-tabla'>Hilo: " + escaparHtmlAbmInsumos(f.asunto_hilo) + "</small>" : "") + "</td>";
					html += "<td class='tdRegistroSearch' style='width:20%'>" + escaparHtmlAbmInsumos(f.nombre_consultorio) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:9%;text-align:center'>" + escaparHtmlAbmInsumos(f.total_insumos) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:15%'>" + escaparHtmlAbmInsumos(f.motivo) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:10%;text-align:center'>" + (pendiente ? "<button type='button' class='btn4 reposicion-recibir-btn' onclick='event.stopPropagation();recibirReposicionInsumos(\"" + escaparHtmlAbmInsumos(f.codigo) + "\")'>Recibir</button>" : "Recibida") + "</td>";
					html += "</tr></table>";
				}
				document.getElementById("tableMovimientosInsumos").innerHTML = html || "<p class='pTituloC' style='padding:14px;text-align:center'>Sin reposiciones.</p>";
				if (codigoReposicionInsumoSeleccionada == "") {
					document.getElementById("tableDetalleMovimientoInsumos").innerHTML = "<p class='pTituloC' style='padding:14px;text-align:center'>Seleccione una reposicion para ver el detalle.</p>";
				}
			} catch (error) {
				document.getElementById("tableMovimientosInsumos").innerHTML = "";
			}
		}
	});
}

function verDetalleReposicionInsumos(codigo) {
	codigoReposicionInsumoSeleccionada = codigo || "";
	actualizarEstadoBotonPdfMovimientoInsumos();
	obtener_datos_user();
	document.getElementById("tableDetalleMovimientoInsumos").innerHTML = paginacargando;
	$.ajax({
		data: {"useru": userid, "passu": passuser, "navegador": navegador, "codigo": codigo, "funt": "detalle_reposicion"},
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				var filas = datos.filas || [];
				var cabecera = datos.cabecera || {};
				var etiquetaHilo = document.getElementById("lblDetalleReposicionHilo");
				if (etiquetaHilo) {
					etiquetaHilo.innerHTML = cabecera.cod_interConsultaFK
						? "Hilo vinculado: <b>" + escaparHtmlAbmInsumos(cabecera.asunto_hilo || ("#" + cabecera.cod_interConsultaFK)) + "</b> &middot; #" + escaparHtmlAbmInsumos(cabecera.cod_interConsultaFK)
						: "Reposici&oacute;n hist&oacute;rica sin Hilo vinculado.";
				}
				var html = "";
				for (var i = 0; i < filas.length; i++) {
					var f = filas[i];
					var nombreDetalle = f.nombre_insumo + (f.nombre_variante ? " - " + f.nombre_variante : "");
					html += "<table class='tableRegistroSearch' border='1' cellspacing='1' cellpadding='5' style='width:100%'><tr>";
					html += "<td class='tdRegistroSearch' style='width:22%'>" + escaparHtmlAbmInsumos(f.nombre_consultorio) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:38%'>" + escaparHtmlAbmInsumos(nombreDetalle) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:15%;text-align:center'>" + escaparHtmlAbmInsumos(formatearCantidadReposicionInsumos(f.cantidad)) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:15%'>" + escaparHtmlAbmInsumos(f.unidad_medida) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:10%;text-align:center'>" + escaparHtmlAbmInsumos(f.insumo_id) + "</td>";
					html += "</tr></table>";
				}
				document.getElementById("tableDetalleMovimientoInsumos").innerHTML = html || "<p class='pTituloC' style='padding:14px;text-align:center'>Sin detalle.</p>";
			} catch (error) {
				document.getElementById("tableDetalleMovimientoInsumos").innerHTML = "";
			}
		}
	});
}

function recibirReposicionInsumos(codigo) {
	if (!confirm("Confirma la recepcion de esta reposicion?\nEl stock de todos los consultorios incluidos se actualizara inmediatamente.")) {
		return;
	}
	obtener_datos_user();
	$.ajax({
		data: {"useru": userid, "passu": passuser, "navegador": navegador, "codigo": codigo, "funt": "recibir_reposicion"},
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) == true) {
					ver_vetana_informativa(datos.mensaje || "Recepcion confirmada.");
					codigoReposicionInsumoSeleccionada = codigo;
					listarReposicionesInsumos();
					verDetalleReposicionInsumos(codigo);
					buscarDashboardInsumosStock();
					listarAlertasStockInsumos();
				} else {
					ver_vetana_informativa(datos.mensaje || "No se pudo confirmar la recepcion.", "", "error");
				}
			} catch (error) {
				GuardarArchivosLog("Error recibirReposicionInsumos: " + error + " \r\n Consola: " + responseText);
			}
		}
	});
}

function generarPdfReposicionInsumos(codigo) {
	var codigoInforme = codigo || codigoReposicionInsumoSeleccionada;
	if (codigoInforme == "") {
		ver_vetana_informativa("Seleccione una reposicion para generar el informe.", "", "error");
		return;
	}
	var ventana = window.open('', '_blank');
	if (!ventana) {
		ver_vetana_informativa("No se pudo abrir la vista previa. Habilite ventanas emergentes.", "", "error");
		return;
	}
	ventana.document.open();
	ventana.document.write("<!DOCTYPE html><html lang='es'><head><meta charset='UTF-8'><title>Preparando informe</title></head><body style='font-family:Arial,sans-serif;padding:18px;color:#172033;'>Preparando informe de reposicion...</body></html>");
	ventana.document.close();

	obtener_datos_user();
	verCerrarEfectoCargando("1");
	$.ajax({
		data: {"useru": userid, "passu": passuser, "navegador": navegador, "codigo": codigoInforme, "funt": "reporte_reposicion"},
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		success: function (responseText) {
			verCerrarEfectoCargando("");
			try {
				var datos = $.parseJSON(responseText);
				if (respuestaJqueryAjax(datos["1"]) === true) {
					if (ventana && ventana.document) {
						ventana.document.open();
						ventana.document.write(datos.html || "<!DOCTYPE html><html><body><h3>Error</h3><p>No se pudo generar el informe.</p></body></html>");
						ventana.document.close();
						try { ventana.focus(); } catch (error) { }
					}
				} else {
					if (ventana && ventana.document) {
						ventana.document.open();
						ventana.document.write("<!DOCTYPE html><html><head><meta charset='UTF-8'><title>Error</title></head><body style='font-family:Arial,sans-serif;padding:18px;color:#991b1b;'><h3>No se pudo generar el informe.</h3><p>" + escaparHtmlAbmInsumos(datos.mensaje || "No se pudo generar el informe de insumos.") + "</p></body></html>");
						ventana.document.close();
					}
					ver_vetana_informativa(datos.mensaje || "No se pudo generar el informe.", "", "error");
				}
			} catch (error) {
				if (ventana && ventana.document) {
					ventana.document.open();
					ventana.document.write("<!DOCTYPE html><html><head><meta charset='UTF-8'><title>Error</title></head><body style='font-family:Arial,sans-serif;padding:18px;color:#991b1b;'><h3>No se pudo generar el informe.</h3></body></html>");
					ventana.document.close();
				}
				ver_vetana_informativa("No se pudo preparar el informe de reposicion.", "", "error");
				GuardarArchivosLog("Error generarPdfReposicionInsumos: " + error + " \r\n Consola: " + responseText);
			}
		},
		error: function (jqXHR, textstatus, errorThrowm) {
			verCerrarEfectoCargando("");
			if (ventana && ventana.document) {
				ventana.document.open();
				ventana.document.write("<!DOCTYPE html><html><head><meta charset='UTF-8'><title>Error</title></head><body style='font-family:Arial,sans-serif;padding:18px;color:#991b1b;'><h3>Error al generar el informe.</h3><p>Contacte al administrador.</p></body></html>");
				ventana.document.close();
			}
			manejadordeerroresjquery(jqXHR.status, textstatus, "abmventana");
		}
	});
}

function listarAlertasStockInsumos() {
	obtener_datos_user();
	if (!document.getElementById("tableAlertasStockInsumos")) {
		return;
	}
	document.getElementById("tableAlertasStockInsumos").innerHTML = paginacargando;
	$.ajax({
		data: {"useru": userid, "passu": passuser, "navegador": navegador, "funt": "listar_alertas_stock"},
		url: "/GoodVentaAsisCap/php_system/abmInsumos.php",
		type: "post",
		success: function (responseText) {
			try {
				var datos = $.parseJSON(responseText);
				var filas = datos.filas || [];
				var html = "";
				for (var i = 0; i < filas.length; i++) {
					var f = filas[i];
					var nombreAlerta = f.nombre_insumo + (f.nombre_variante ? " - " + f.nombre_variante : "");
					html += "<table class='tableRegistroSearch insumo-stock-bajo' border='1' cellspacing='1' cellpadding='5' style='width:100%'><tr>";
					html += "<td class='tdRegistroSearch' style='width:18%'>" + escaparHtmlAbmInsumos(f.nombre_local) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:16%'>" + escaparHtmlAbmInsumos(f.nombre_consultorio) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:24%'>" + escaparHtmlAbmInsumos(nombreAlerta) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:10%;text-align:center'>" + escaparHtmlAbmInsumos(f.cantidad) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:10%;text-align:center'>" + escaparHtmlAbmInsumos(f.stock_minimo) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:10%;text-align:center'>" + escaparHtmlAbmInsumos(f.diferencia) + "</td>";
					html += "<td class='tdRegistroSearch' style='width:7%;text-align:center'><span class='insumo-stock-pill insumo-stock-pill--bajo'>Bajo</span></td>";
					html += "<td class='tdRegistroSearch' style='width:5%;text-align:center'><span class='insumos-row-action insumos-row-action--quiet' title='Registrar entrada desde Movimientos'>Entrada</span></td>";
					html += "</tr></table>";
				}
				document.getElementById("tableAlertasStockInsumos").innerHTML = html || "<p class='pTituloC' style='padding:14px;text-align:center'>Sin alertas activas.</p>";
				if (document.getElementById("contadorAlertasInsumos")) {
					document.getElementById("contadorAlertasInsumos").textContent = filas.length;
				}
			} catch (error) {
				document.getElementById("tableAlertasStockInsumos").innerHTML = "";
			}
		}
	});
}


